window.PAPERS=[{"id": 1, "title": "Foundations & SQL reasoning", "lectures": "01–03", "questions": [{"id": "p1q1", "type": "multi", "topic": "Design decisions", "scenario": "A clinic proposes storing patients, appointments and invoices in separate spreadsheets. Staff often overwrite another user’s changes. The team proposes a DBMS.", "prompt": "Which conclusions are justified?", "code": null, "options": [{"text": "Receptionists need a duplicate patient table in order to see fewer patient columns.", "correct": false, "why": "A restricted view can expose fewer columns without duplicating patient records."}, {"text": "Access controls can give receptionists a narrower view than clinicians.", "correct": true, "why": "Views and permissions can restrict exposed data."}, {"text": "Keeping a continuously updated replica is enough to recover yesterday’s data after an accidental deletion, even without retained history.", "correct": false, "why": "The accidental deletion can propagate to the replica; retained backups or history are needed for an earlier state."}, {"text": "Database design must still identify patient and appointment identities.", "correct": true, "why": "A DBMS does not discover the correct business model automatically."}, {"text": "Concurrency control can reduce overwrite risk, but application transactions must use it appropriately.", "correct": true, "why": "A DBMS provides coordination facilities; simply moving data does not prove every workflow uses them correctly."}], "explanation": "Separate facilities the DBMS provides from policies and transactions the team must still design. A replica is not automatically a recoverable history.", "source": "Lecture 01, slides 6, 9–12, 20; recovery/concurrency application."}, {"id": "p1q2", "type": "multi", "topic": "Independence", "scenario": "A library moves table storage from one disk layout to another. Its table definitions and application queries remain unchanged. Later it adds a column while keeping an existing user view unchanged.", "prompt": "Which interpretations follow?", "code": null, "options": [{"text": "Preserving the view after adding a column can illustrate logical independence.", "correct": true, "why": "The user interface can remain stable despite a conceptual schema extension."}, {"text": "Preserving one existing view proves that an application querying the new column directly will also need no change.", "correct": false, "why": "Independence of one interface does not establish independence for every application interface."}, {"text": "The user view and physical storage are different abstraction levels.", "correct": true, "why": "External and internal representations serve different concerns."}, {"text": "The disk change illustrates physical data independence.", "correct": true, "why": "Storage changed without a logical interface change."}, {"text": "Adding the new table column changes the logical schema even though the old user view stays stable.", "correct": true, "why": "A conceptual schema extension can be hidden behind a stable external view."}], "explanation": "Track which abstraction level changed and which interface remained stable. Stability of one view is not a guarantee about every application.", "source": "Lecture 01, slides 10–11; physical/logical independence application."}, {"id": "p1q3", "type": "multi", "topic": "Design phases", "scenario": "A university team records that each course has one coordinator, draws an ER model, converts it to tables, then chooses indexes.", "prompt": "Which reviews identify the appropriate work?", "code": null, "options": [{"text": "A correct ER diagram guarantees that every later relational mapping is free of redundancy, so refinement can be skipped.", "correct": false, "why": "The mapping still needs refinement; a sound conceptual model does not certify every implementation choice."}, {"text": "Performance and access-control requirements should first be collected after physical indexes have been selected.", "correct": false, "why": "Requirements analysis identifies performance and security constraints before later design choices are evaluated."}, {"text": "Confirm the coordinator rule during requirements analysis.", "correct": true, "why": "The rule should be established with stakeholders before implementing it."}, {"text": "Choose disk indexes as part of conceptual ER modelling.", "correct": false, "why": "Indexes are physical design choices."}, {"text": "Mapping the ER model to relational tables is logical design.", "correct": true, "why": "Logical design selects the database-model representation."}], "explanation": "Requirements constrain all later design decisions. Logical mapping, refinement, physical indexing and access design solve different problems.", "source": "Lecture 01, slides 12–20."}, {"id": "p1q4", "type": "multi", "topic": "Hosting trade-offs", "scenario": "A small team needs a hosted reservation database, has little operations staff, and must meet a specified backup retention policy. A vendor offers managed hosting.", "prompt": "Which actions are justified?", "code": null, "options": [{"text": "Evaluate network latency and availability against reservation needs.", "correct": true, "why": "Remote access adds network and service dependencies."}, {"text": "Check whether the service actually meets the retention requirement.", "correct": true, "why": "Managed does not automatically mean every retention policy is satisfied."}, {"text": "If the provider manages database patches, the application team no longer needs to decide who may read reservation details.", "correct": false, "why": "Operational maintenance does not decide business authorization rules."}, {"text": "Compare operating effort and total cost, not only disk price.", "correct": true, "why": "Management effort is part of the hosting decision."}, {"text": "A managed cloud service can host a relational database; cloud hosting does not require a NoSQL model.", "correct": true, "why": "Hosting location and management model are distinct from the data model; the lecture lists relational cloud services."}], "explanation": "Choose hosting against the actual retention, latency, management and cost needs; neither location nor managed maintenance decides the data model or business permissions.", "source": "Lecture 01, slides 20–25."}, {"id": "p1q5", "type": "multi", "topic": "Metadata and data-intensive workloads", "scenario": "A telemetry service stores a million readings per hour but performs only simple arithmetic on each reading. A developer reads column types from the catalog. The DBA saves backups and the service has a two-minute recovery requirement.", "prompt": "Which assessments follow?", "code": null, "options": [{"text": "Column definitions in the catalog are metadata.", "correct": true, "why": "They describe the structure and types of application data."}, {"text": "The service cannot be data-intensive because each calculation is simple.", "correct": false, "why": "Data-intensive workloads can be dominated by data volume, retrieval and storage rather than complex calculations."}, {"text": "The large reading stream makes storage throughput, retrieval and growth relevant design concerns.", "correct": true, "why": "The workload must reliably handle large and growing volumes of data."}, {"text": "Successful creation of a backup file alone proves the two-minute recovery requirement is met.", "correct": false, "why": "Recovery time depends on restoring and making the service usable; that must be evaluated separately."}, {"text": "Staff recovery procedures are outside the database system environment because they are not executable SQL.", "correct": false, "why": "The database system environment includes people and procedures, as well as hardware, software and data."}], "explanation": "Data-intensive does not mean computation-intensive. High data volume and modest arithmetic can still demand careful storage and recovery engineering.", "source": "Lecture 01, slides 9–11, 26–30."}, {"id": "p1q6", "type": "multi", "topic": "CHECK and NULL", "scenario": "A shop creates Product(pid int PRIMARY KEY, price decimal(8,2) NULL CHECK(price>=0)). No other constraints or triggers exist.", "prompt": "Which inserts satisfy these constraints?", "code": null, "options": [{"text": "A previously unused pid with price -1.", "correct": false, "why": "The CHECK evaluates FALSE."}, {"text": "A previously unused pid with price 0.", "correct": true, "why": "Zero satisfies price>=0."}, {"text": "An already existing pid with a different valid price.", "correct": false, "why": "The primary key must remain unique."}, {"text": "A NULL pid with a valid price.", "correct": false, "why": "Primary-key columns cannot be NULL."}, {"text": "A previously unused pid with price NULL.", "correct": true, "why": "The price comparison is UNKNOWN, which CHECK does not reject; price is nullable."}], "explanation": "A primary key rejects NULL and duplicates. A nullable price with CHECK(price>=0) rejects negative values, but UNKNOWN does not fail the CHECK.", "source": "Lecture 02, slides 6–7; SQL Server CHECK/NULL semantics."}, {"id": "p1q7", "type": "multi", "topic": "Constraint placement", "scenario": "A developer wants an enrolment identified by the pair (sid,cid), with sid referencing Student and cid referencing Course.", "prompt": "Which implementation decisions are valid?", "code": null, "options": [{"text": "An enabled FK may reference a parent table that will only be created later in the same batch.", "correct": false, "why": "The referenced parent must exist when the FK is established; create it first or add the FK later."}, {"text": "Use one FK for sid and a separate FK for cid.", "correct": true, "why": "The columns reference two different parent keys."}, {"text": "A composite primary key makes sid alone unique.", "correct": false, "why": "Only the complete pair must be unique."}, {"text": "Use one table-level PRIMARY KEY(sid,cid).", "correct": true, "why": "A composite key is expressed as one constraint over both columns."}, {"text": "Declare sid PRIMARY KEY and cid PRIMARY KEY as two independent primary keys.", "correct": false, "why": "A table has one primary-key constraint; these declarations do not create the intended pair key."}], "explanation": "The identity is one pair, not two independent unique columns. Referenced objects must exist when enabled references are created.", "source": "Lecture 02, slides 6–8; Lab 03 constraints."}, {"id": "p1q8", "type": "multi", "topic": "Referential actions", "scenario": "Dept has rows 10 and 20. Employee(eid PK,did NULL FK→Dept.did ON DELETE SET NULL) contains (1,10),(2,10),(3,20).", "prompt": "After deleting Dept 10, which statements hold?", "code": null, "options": [{"text": "Dept 20 remains.", "correct": true, "why": "Only department 10 was deleted."}, {"text": "The action would work unchanged if did were NOT NULL.", "correct": false, "why": "SET NULL requires nullable referencing columns."}, {"text": "Employees 1 and 2 remain.", "correct": true, "why": "SET NULL changes the reference instead of deleting child rows."}, {"text": "Employees 1 and 2 have NULL did.", "correct": true, "why": "That is the specified referential action."}, {"text": "If ON DELETE CASCADE were used instead, employees 1 and 2 would be deleted with Dept 10.", "correct": true, "why": "CASCADE removes referencing child rows rather than setting their references to NULL."}], "explanation": "Trace the specified referential action separately from the parent deletion. SET NULL and CASCADE produce different child outcomes.", "source": "Lecture 02, slide 7; referential-action application."}, {"id": "p1q9", "type": "multi", "topic": "NULL filtering", "scenario": "Reading(rid PK,value NULL) contains (1,5),(2,NULL),(3,0).", "prompt": "Which query/result claims are correct?", "code": null, "options": [{"text": "WHERE value=5 OR value IS NULL returns rid 1 and rid 2.", "correct": true, "why": "Each of those rows satisfies one side of the disjunction."}, {"text": "WHERE value<>5 returns only rid 3.", "correct": true, "why": "NULL<>5 is UNKNOWN, not TRUE."}, {"text": "WHERE value=5 OR value<>5 returns only rid 1 and rid 3.", "correct": true, "why": "For NULL both comparisons are UNKNOWN, so their OR is still UNKNOWN and rid 2 is excluded."}, {"text": "WHERE value IS NULL returns rid 2.", "correct": true, "why": "IS NULL directly tests missing values."}, {"text": "WHERE NOT(value=5) returns rid 2 and rid 3.", "correct": false, "why": "NOT UNKNOWN remains UNKNOWN, so rid 2 is excluded."}], "explanation": "SQL predicates must be TRUE to survive WHERE. UNKNOWN is not FALSE, and negation does not turn UNKNOWN into TRUE.", "source": "Lecture 02, slides 12–14; SQL three-valued logic."}, {"id": "p1q10", "type": "multi", "topic": "Operator precedence", "scenario": "Offer(id,region,price) contains (1,East,150),(2,West,80),(3,West,150),(4,North,50).", "prompt": "Which claims about the following filter are correct?", "code": "WHERE region='East' OR region='West' AND price<100", "options": [{"text": "Offer 1 is selected.", "correct": true, "why": "AND binds before OR, so every East row satisfies the left branch."}, {"text": "Offer 2 would be excluded unless parentheses were added around the region comparisons.", "correct": false, "why": "The original predicate already accepts West rows whose price is below 100."}, {"text": "Offer 3 is selected.", "correct": false, "why": "It fails the price requirement on the West branch."}, {"text": "Adding parentheses around the two region tests would remove offer 1.", "correct": true, "why": "Then the price condition would also apply to East."}, {"text": "Offer 4 is selected because its price is below 100.", "correct": false, "why": "It satisfies neither region branch."}], "explanation": "Evaluate AND before OR. The price restriction belongs to the West branch until parentheses change the expression.", "source": "Lecture 02, slides 11–12; combined predicate application."}, {"id": "p1q11", "type": "multi", "topic": "Aggregation", "scenario": "Payment(pid,amount decimal(8,2) NULL) has rows (1,100),(2,NULL),(3,200),(4,100).", "prompt": "Which results follow without grouping?", "code": null, "options": [{"text": "COUNT(amount) = 3.", "correct": true, "why": "The NULL amount is ignored."}, {"text": "AVG(amount) = 100.", "correct": false, "why": "The average is 400/3, not 400/4."}, {"text": "SUM(amount) = 400.", "correct": true, "why": "The three known amounts sum to 400."}, {"text": "COUNT(DISTINCT amount) = 3.", "correct": false, "why": "Only two distinct non-NULL amounts exist: 100 and 200."}, {"text": "COUNT(*) = 4.", "correct": true, "why": "All rows are counted."}], "explanation": "Count rows separately from known values and distinct known values. AVG uses three non-NULL decimal values here.", "source": "Lecture 02, slides 18–19."}, {"id": "p1q12", "type": "multi", "topic": "WHERE versus HAVING", "scenario": "Sale(agent,amount) contains (A,40),(A,80),(B,100),(B,20). A manager wants agents whose total sales exceed 110, counting all their sales.", "prompt": "Which query fragments or result claims correctly support that request?", "code": null, "options": [{"text": "SELECT agent,SUM(amount) with the correct grouping.", "correct": true, "why": "The total per agent is the requested measure."}, {"text": "HAVING amount>110 without grouping or aggregation of amount.", "correct": false, "why": "The individual amount is not a valid group-level expression here."}, {"text": "DISTINCT is required to keep both agents because their aggregate totals are equal.", "correct": false, "why": "The rows have different agent values; GROUP BY already produces one row per agent, regardless of equal totals."}, {"text": "GROUP BY agent HAVING SUM(amount)>110.", "correct": true, "why": "Both A and B have totals of 120."}, {"text": "WHERE amount>110 GROUP BY agent.", "correct": false, "why": "Filtering individual rows removes every row before totals are formed."}], "explanation": "WHERE acts on individual sales before grouping; HAVING acts on each agent’s total after grouping. Both totals are 120.", "source": "Lecture 02, slides 20–23."}, {"id": "p1q13", "type": "multi", "topic": "Left-join counting", "scenario": "Member has IDs 1,2,3. Loan(lid PK,mid FK) contains (10,1),(11,1),(12,2).", "prompt": "For the query below, which claims are true?", "code": "SELECT m.mid,COUNT(l.lid) n\nFROM Member m LEFT JOIN Loan l ON l.mid=m.mid\nGROUP BY m.mid;", "options": [{"text": "The join produces four rows before grouping.", "correct": true, "why": "Two for member 1, one for member 2, one unmatched row for member 3."}, {"text": "After changing to INNER JOIN, COUNT(*) and COUNT(l.lid) agree for every remaining member group.", "correct": true, "why": "Every retained joined row has a non-NULL matching loan primary key."}, {"text": "Member 1 has n=2.", "correct": true, "why": "Two child rows match."}, {"text": "Member 3 has n=0.", "correct": true, "why": "COUNT(l.lid) ignores the NULL-extended child value."}, {"text": "Replacing COUNT(l.lid) with COUNT(*) still gives member 3 zero.", "correct": false, "why": "The preserved row itself is counted by COUNT(*)."}], "explanation": "Expand the join before counting: member 1 has two rows, member 2 one, and member 3 one NULL-extended row.", "source": "Lecture 03, slide 6; Lecture 02 aggregation."}, {"id": "p1q14", "type": "multi", "topic": "Outer-join filters", "scenario": "Member has IDs 1,2,3. Loan(lid,mid,state) contains (10,1,Open),(11,2,Closed). The report must include every member and count only open loans.", "prompt": "Which changes or conclusions are valid?", "code": null, "options": [{"text": "WHERE l.state='Open' OR l.lid IS NULL always fixes the problem.", "correct": false, "why": "Member 2 has a matched Closed loan, so it gets no NULL-extended row and is removed."}, {"text": "Put l.state='Open' in the LEFT JOIN ON condition.", "correct": true, "why": "The match is restricted while unmatched parents remain."}, {"text": "Put l.state='Open' only in WHERE after the LEFT JOIN.", "correct": false, "why": "This removes members whose joined state is Closed or NULL."}, {"text": "With the open-loan predicate in ON, use COUNT(l.lid), grouped by member ID.", "correct": true, "why": "After restricting matches to open loans, COUNT of the child key counts qualifying children and gives zero for missing matches."}, {"text": "With the correct ON filter, members 2 and 3 both receive zero.", "correct": true, "why": "Neither has a qualifying open loan."}], "explanation": "A Closed child is a real match before a WHERE filter. Filtering matches in ON is what creates a preserved zero-open-loan group for that member.", "source": "Lecture 03, slides 5–6; outer-join filter application."}, {"id": "p1q15", "type": "multi", "topic": "Join multiplication", "scenario": "One customer has two orders with distinct non-NULL orderIDs and three independent support tickets with distinct ticketIDs. A query joins Customer to Orders and Ticket using customer ID, with no other restrictions.", "prompt": "Which statements follow?", "code": null, "options": [{"text": "The customer contributes six joined rows.", "correct": true, "why": "Each of the two orders pairs with each of three tickets."}, {"text": "COUNT(orderID) over that join is two.", "correct": false, "why": "Each order appears three times, producing six counted values."}, {"text": "COUNT(DISTINCT orderID) gives two for this customer.", "correct": true, "why": "Distinct removes the repeated order IDs."}, {"text": "Pre-aggregating orders and tickets separately can prevent inflated counts.", "correct": true, "why": "One summary row per customer avoids the two-by-three multiplication."}, {"text": "SUM(DISTINCT orderAmount) is always a safe repair for inflated revenue.", "correct": false, "why": "Two genuinely different orders may have the same amount and would be wrongly merged."}], "explanation": "Two independent one-to-many joins produce a two-by-three product. Removing duplicate values is not the same as counting distinct business objects.", "source": "Lecture 03, slides 4–6; Lecture 02 aggregation."}, {"id": "p1q16", "type": "multi", "topic": "Inner-join alternatives", "scenario": "Employee(eid,did) and Dept(did,name) are joined on matching department ID. The intended result excludes employees without a matching department.", "prompt": "Which implementations or claims are valid?", "code": null, "options": [{"text": "FROM Employee e, Dept d WHERE e.did=d.did.", "correct": true, "why": "The predicate filters the Cartesian product to matching pairs."}, {"text": "FROM Employee e, Dept d with no predicate gives the same result in every database.", "correct": false, "why": "It returns every pair, not only matching pairs."}, {"text": "Replacing INNER JOIN with LEFT JOIN, without a later filter, still guarantees unmatched employees are excluded.", "correct": false, "why": "LEFT JOIN preserves unmatched employees, contrary to the intended report."}, {"text": "An inner join always produces one row per employee regardless of the right table.", "correct": false, "why": "Multiplicity depends on matching rows and constraints."}, {"text": "FROM Employee e JOIN Dept d ON e.did=d.did.", "correct": true, "why": "This is an explicit inner join."}], "explanation": "Implicit and explicit inner joins express the same matching-pair condition. A left join changes unmatched-row preservation.", "source": "Lecture 03, slides 4–5."}, {"id": "p1q17", "type": "multi", "topic": "Right join", "scenario": "Book has IDs 10,20. Loan(lid,bid) contains only (1,10). A report uses Loan RIGHT JOIN Book ON Loan.bid=Book.bid.", "prompt": "Which statements are correct?", "code": null, "options": [{"text": "Swapping table order to Book LEFT JOIN Loan with the same ON condition preserves the same book/loan pairings.", "correct": true, "why": "Both formulations preserve Book; compare the same explicitly selected columns rather than SELECT * column order."}, {"text": "Book 10 appears with loan ID 1.", "correct": true, "why": "The matching pair is retained."}, {"text": "For the unmatched book 20, Book.bid remains 20 while Loan.bid is NULL in the result.", "correct": true, "why": "Only the missing Loan-side columns are NULL-extended; the preserved Book row retains its own values."}, {"text": "Book 20 appears with a NULL loan ID.", "correct": true, "why": "The right table is preserved."}, {"text": "Book 20 is removed because it has no loan.", "correct": false, "why": "That would be inner-join behaviour."}], "explanation": "The preserved Book side keeps its values, while missing Loan-side values become NULL. This changes query results, not stored records.", "source": "Lecture 03, slides 6–7."}, {"id": "p1q18", "type": "multi", "topic": "IN and NOT IN", "scenario": "Employee IDs are 1,2,3. Assignment.ownerID contains 1 and NULL.", "prompt": "Which conclusions follow under SQL NULL rules?", "code": null, "options": [{"text": "Filtering NULL out of the NOT IN subquery makes employees 2 and 3 pass.", "correct": true, "why": "The remaining set contains only 1."}, {"text": "NULL in the subquery matches every employee ID.", "correct": false, "why": "NULL comparisons are unknown, not universal matches."}, {"text": "eid IN (SELECT ownerID FROM Assignment) returns employee 1.", "correct": true, "why": "The comparison finds a true match for 1."}, {"text": "eid NOT IN (SELECT ownerID FROM Assignment) returns employees 2 and 3.", "correct": false, "why": "The NULL causes UNKNOWN for those nonmatching IDs."}, {"text": "A correlated NOT EXISTS test can find employees 2 and 3.", "correct": true, "why": "Neither has an equal ownerID row; NULL does not match their IDs."}], "explanation": "A NULL inside NOT IN can make every nonmatching comparison UNKNOWN. A properly correlated NOT EXISTS asks whether an equal row exists.", "source": "Lecture 02, slide 12; Lab 08 nested queries; SQL NULL semantics."}, {"id": "p1q19", "type": "multi", "topic": "Scalar subqueries", "scenario": "Book prices are 100,200,200. A student writes price=(SELECT price FROM Book) in a WHERE clause.", "prompt": "Which observations are correct?", "code": null, "options": [{"text": "A zero-row scalar subquery normally behaves as the number zero.", "correct": false, "why": "It yields NULL, not numeric zero."}, {"text": "The scalar subquery fails because it returns more than one row.", "correct": true, "why": "A scalar expression cannot accept these three rows."}, {"text": "The repeated 200 automatically collapses the result to one row.", "correct": false, "why": "SQL does not remove duplicate rows implicitly, and even DISTINCT gives 100 and 200."}, {"text": "Replacing the subquery with SELECT MAX(price) returns the two highest-priced books.", "correct": true, "why": "MAX returns the single scalar 200."}, {"text": "Using price IN (SELECT price FROM Book) accepts all three books here.", "correct": true, "why": "Each price belongs to that set."}], "explanation": "A scalar subquery permits at most one row. An aggregate can produce one scalar; IN deliberately accepts a multiple-row result.", "source": "Lecture 02, slide 12; Lab 08 single-row subqueries."}, {"id": "p1q20", "type": "multi", "topic": "ANY and ALL", "scenario": "A comparison subquery returns the non-NULL values 40 and 70. A product price is 60.", "prompt": "Which claims are true?", "code": null, "options": [{"text": "60 > ANY(subquery) is true.", "correct": true, "why": "60 exceeds at least one value: 40."}, {"text": "Replacing ANY with SOME leaves these comparisons unchanged.", "correct": true, "why": "SOME and ANY are SQL synonyms."}, {"text": "60 < ANY(subquery) is true.", "correct": true, "why": "60 is below 70."}, {"text": "For an empty subquery, >ALL is true.", "correct": true, "why": "Universal comparison over an empty set is true."}, {"text": "For an empty subquery, >ANY is true.", "correct": false, "why": "There is no witness satisfying the comparison."}], "explanation": "ANY/SOME needs a true witness; ALL needs no counterexample. This explains both the 40/70 comparisons and the empty-set results.", "source": "Lecture 02, slide 12; Lab 08 ANY/ALL."}, {"id": "p1q21", "type": "multi", "topic": "Sorting and duplicate removal", "scenario": "Book contains (1,SQL,100),(2,SQL,100),(3,ER,120), with columns bid,title,price.", "prompt": "Which claims are correct?", "code": null, "options": [{"text": "SELECT DISTINCT bid,title,price returns two rows.", "correct": false, "why": "The different primary keys keep all three projected tuples distinct."}, {"text": "ORDER BY price DESC,bid ASC places bid 3 first.", "correct": true, "why": "120 is the highest price."}, {"text": "TOP(1) without ORDER BY guarantees bid 3.", "correct": false, "why": "No deterministic ordering is specified."}, {"text": "Adding bid to the ORDER BY makes the tied 100-price rows ordered deterministically.", "correct": true, "why": "The unique bid breaks the tie."}, {"text": "SELECT DISTINCT title,price returns two rows.", "correct": true, "why": "The first two rows become one identical projected pair."}], "explanation": "DISTINCT applies to the whole projected tuple. Stable TOP selection needs ordering, and tied prices need a unique tie-breaker.", "source": "Lecture 02, slides 15, 17; SQL Server TOP application."}, {"id": "p1q22", "type": "multi", "topic": "Pattern and interval filters", "scenario": "Code values are AB12, AB123, XB12 and AB1. Numeric scores are checked independently with BETWEEN 50 AND 80.", "prompt": "Which statements are correct?", "code": null, "options": [{"text": "LIKE 'AB%' excludes AB1.", "correct": false, "why": "Percent may match any suffix length, including one character."}, {"text": "BETWEEN 50 AND 80 includes both boundary scores.", "correct": true, "why": "BETWEEN is inclusive."}, {"text": "BETWEEN 50 AND 80 includes a NULL score.", "correct": false, "why": "The comparisons are UNKNOWN for NULL."}, {"text": "LIKE 'AB__' matches AB12 but not AB123.", "correct": true, "why": "Two underscores require exactly two following characters."}, {"text": "LIKE '%B12' matches AB12 and XB12.", "correct": true, "why": "The percent accepts either prefix."}], "explanation": "Match the whole code against the pattern. Percent matches any-length suffix, underscore one character, and BETWEEN includes both numeric endpoints.", "source": "Lecture 02, slides 13, 16."}, {"id": "p1q23", "type": "multi", "topic": "Changing records", "scenario": "A shop has three Product rows. The developer runs UPDATE Product SET price=price*1.1 with no WHERE, then DELETE FROM Product WHERE pid=999, where no such ID exists.", "prompt": "Which conclusions follow?", "code": null, "options": [{"text": "DROP TABLE Product would remove rows but retain the empty table definition for later INSERT statements.", "correct": false, "why": "DROP removes the table object; DELETE removes rows while retaining the table."}, {"text": "The UPDATE automatically creates an audit history table.", "correct": false, "why": "No such trigger or auditing setup was specified."}, {"text": "The UPDATE targets every product row.", "correct": true, "why": "No WHERE limits its target set."}, {"text": "The DELETE removes all three rows because 999 is absent.", "correct": false, "why": "A nonmatching predicate deletes zero rows."}, {"text": "The table definition remains after the DELETE.", "correct": true, "why": "DELETE removes qualifying rows, not the table object."}], "explanation": "Separate row-changing statements from object-changing statements. An absent match deletes nothing; missing WHERE targets all rows.", "source": "Lecture 02, slides 6, 8–10."}, {"id": "p1q24", "type": "multi", "topic": "Empty input aggregates", "scenario": "A report filters all Payment rows out before aggregating and does not use GROUP BY.", "prompt": "Which result claims are correct?", "code": null, "options": [{"text": "The ungrouped aggregate query necessarily returns no result row.", "correct": false, "why": "It returns one aggregate row even with no input rows."}, {"text": "COUNT(*) returns zero.", "correct": true, "why": "No input rows are counted."}, {"text": "SUM(amount) returns NULL.", "correct": true, "why": "SUM has no non-NULL input values."}, {"text": "COALESCE(SUM(amount),0) returns zero.", "correct": true, "why": "COALESCE substitutes the requested default."}, {"text": "MIN(amount) returns NULL.", "correct": true, "why": "There is no input value from which to compute a minimum."}], "explanation": "An ungrouped aggregate returns one summary row even with empty input. COUNT has result zero; SUM/MIN/AVG have NULL unless replaced.", "source": "Lecture 02, slides 18–19; empty-input aggregate application."}, {"id": "p1q25", "type": "multi", "topic": "Combined report diagnosis", "scenario": "Customer IDs are 1,2. Order(oid,cid,total) contains (10,1,50),(11,1,50). The goal is every customer with total order value, using zero where no order exists.", "prompt": "Which proposed repairs are correct?", "code": null, "options": [{"text": "Use LEFT JOIN, GROUP BY customer ID, and COALESCE(SUM(o.total),0).", "correct": true, "why": "That preserves customer 2 and replaces its NULL sum with zero."}, {"text": "Use SUM(DISTINCT o.total) to ensure customer 1 receives 100.", "correct": false, "why": "DISTINCT collapses the two equal amounts and gives 50."}, {"text": "Expect customer 1 to receive 100.", "correct": true, "why": "Two different orders each contribute 50."}, {"text": "Expect customer 2 to receive 0 after COALESCE.", "correct": true, "why": "Its preserved group has no non-NULL order value."}, {"text": "Put o.total>0 in WHERE and still guarantee every customer appears.", "correct": false, "why": "The NULL-extended row for customer 2 fails that predicate."}], "explanation": "Preserve customers first, aggregate each customer’s real orders, then substitute zero for the missing total. Equal order values are still separate revenue.", "source": "Lecture 03, slide 6; Lecture 02, slides 18–23."}]}, {"id": 2, "title": "EER design & relational mapping", "lectures": "04–05", "questions": [{"id": "p2q1", "type": "multi", "topic": "Weak task identity", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Projects P1 and P2 both contain a task numbered 7.", "prompt": "Which mapping decisions preserve the task rules?", "options": [{"text": "Make Task.pid UNIQUE to enforce the identifying relationship.", "correct": false, "why": "That would permit at most one task per project, contradicting the many side."}, {"text": "Store a separate Project foreign key for each digit of taskNo.", "correct": false, "why": "Foreign keys reference entity keys, not the internal characters of a partial key."}, {"text": "Use (pid, taskNo) as the Task primary key.", "correct": true, "why": "The partial key taskNo becomes unique when combined with its owner project key."}, {"text": "Include a Task.pid foreign key referencing Project.pid.", "correct": true, "why": "Every task must refer to an existing owner project."}, {"text": "Use taskNo alone as the Task primary key.", "correct": false, "why": "Task numbers can repeat in different projects."}], "explanation": "An identifying relationship contributes the owner key to both the weak entity primary key and its foreign-key reference.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q2", "type": "multi", "topic": "Multivalued phones", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Two departments share a switchboard number; another department has no phone recorded.", "prompt": "Which statements follow from a conventional mapping of Department.phone?", "options": [{"text": "DepartmentPhone.did references Department.did.", "correct": true, "why": "Each phone entry belongs to a real department."}, {"text": "The absence of DepartmentPhone rows automatically violates the diagram.", "correct": false, "why": "No minimum number of phone values is specified."}, {"text": "The multivalued attribute requires one new foreign key for every stored phone number.", "correct": false, "why": "One foreign-key constraint applies to all rows; data rows do not create new constraints."}, {"text": "DepartmentPhone(did, phone) can use the pair as its primary key.", "correct": true, "why": "The pair prevents the same phone value appearing twice for one department."}, {"text": "The phone column must be globally UNIQUE.", "correct": false, "why": "The scenario permits two departments to share a number."}], "explanation": "A multivalued attribute becomes a separate relation; constraints are counted per schema declaration, not per stored value.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q3", "type": "multi", "topic": "Ownership participation", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. A designer adds did to Project to represent Owns.", "prompt": "Which choices are justified?", "options": [{"text": "Project.did should be NOT NULL.", "correct": true, "why": "Every project has exactly one owning department."}, {"text": "A foreign key from Department to one Project is sufficient to represent all owned projects.", "correct": false, "why": "One scalar project reference cannot represent an arbitrary collection of projects."}, {"text": "A department with no projects can satisfy the diagram.", "correct": true, "why": "Department participation in Owns has minimum zero."}, {"text": "Project.did should reference Department.did.", "correct": true, "why": "Project is the many side and holds the owner reference."}, {"text": "Project.did must be UNIQUE.", "correct": false, "why": "A department may own several projects."}], "explanation": "The maximum cardinality places the FK on Project; the minimum participation makes that FK mandatory.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q4", "type": "multi", "topic": "Overlapping partial ISA", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Person 20 has no role row, Person 21 has a Staff row, and Person 22 has both Staff and Student rows.", "prompt": "Which observations are valid?", "options": [{"text": "Person 21 need not have a Student row.", "correct": true, "why": "Overlap permits several roles but does not require them."}, {"text": "Each Staff row must correspond to a Person row in a parent-plus-subtype mapping.", "correct": true, "why": "The inherited subtype primary key is also a foreign key to Person."}, {"text": "Person 20 is allowed by partial specialisation.", "correct": true, "why": "Partial specialisation allows a superclass instance in no subtype."}, {"text": "Person 22 violates disjointness.", "correct": false, "why": "This specialisation is overlapping, not disjoint."}, {"text": "Person 22 inherits the same Person identity in both roles.", "correct": true, "why": "Subtype identities are inherited from the superclass."}], "explanation": "Overlap answers whether roles can coexist; partiality answers whether a role is required. These are independent decisions.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q5", "type": "multi", "topic": "Choosing ISA alternatives", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. The team wants to replace Person, Staff and Student with a different ISA mapping.", "prompt": "Which assessments are correct?", "options": [{"text": "Keeping only Staff and Student always preserves every Person.", "correct": false, "why": "A person in neither role would have no table in which to be represented."}, {"text": "Keeping Person plus both subtype tables can represent all permitted cases.", "correct": true, "why": "This general mapping supports both partiality and overlap."}, {"text": "The two role flags must always sum to exactly one.", "correct": false, "why": "The scenario allows both zero roles and two roles."}, {"text": "One ordinary discriminator with mutually exclusive Staff/Student values cannot express dual membership.", "correct": true, "why": "A single exclusive value does not represent overlapping roles."}, {"text": "One Person table with separate isStaff and isStudent flags can represent the ISA.", "correct": true, "why": "Two flags can represent neither, either or both roles."}], "explanation": "Select an ISA mapping by both covering and disjointness constraints, not merely by the number of subtypes.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q6", "type": "multi", "topic": "Recursive mentorship", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Mentorship is implemented using Person.mentorID.", "prompt": "Which statements are correct?", "options": [{"text": "The self-referencing FK alone rejects every cycle involving two or more people.", "correct": false, "why": "Every reference in a cycle may point to an existing person, so the FK can still hold."}, {"text": "mentorID should reference Person.personID.", "correct": true, "why": "Both roles of the recursive relationship use the same entity type."}, {"text": "A CHECK comparing mentorID with personID can reject self-mentoring.", "correct": true, "why": "A direct inequality check rejects a person being their own mentor."}, {"text": "mentorID must be nullable to represent an unmentored person.", "correct": true, "why": "The mentee minimum is zero."}, {"text": "UNIQUE(mentorID) is needed to allow one mentor to guide many people.", "correct": false, "why": "UNIQUE would instead prevent repeated use of the same mentor."}], "explanation": "A self-FK checks existence. Maximum cardinality, optionality, self-links and longer cycles are separate constraints.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q7", "type": "multi", "topic": "Aggregation and foreign keys", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Review stores staffID, personID, pid and verdict. Participation uses primary key (personID,pid).", "prompt": "Which choices correctly preserve what is reviewed?", "options": [{"text": "Separate FKs to Person and Project are equivalent to the composite reference to Participation.", "correct": false, "why": "They verify individual entities but not the existence of their participation pair."}, {"text": "Use a separate FK from Review.staffID to Staff.personID.", "correct": true, "why": "The reviewer must be a staff member."}, {"text": "The two intended FK constraints use three referencing columns in total.", "correct": true, "why": "staffID contributes one; the participation FK contributes two."}, {"text": "Use a composite FK (personID,pid) from Review to Participation.", "correct": true, "why": "This verifies that the exact person–project participation exists."}, {"text": "These references consist of three FK constraints because they use three columns.", "correct": false, "why": "They are two constraints: one single-column and one composite."}], "explanation": "Aggregation preserves the identity of an association. The number of FK constraints is not the number of FK columns.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q8", "type": "multi", "topic": "Relationship attributes", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Person 8 participates in Project A for 12 hours and Project B for 30 hours. Staff member 4 reviews both participations with different verdicts.", "prompt": "Which placements preserve these facts?", "options": [{"text": "Store verdict in Review.", "correct": true, "why": "Verdict describes a particular staff review of a particular participation."}, {"text": "Store one hours value in Person.", "correct": false, "why": "One value cannot distinguish Person 8’s two projects."}, {"text": "Store one verdict in Staff.", "correct": false, "why": "A reviewer can give different verdicts to different participations."}, {"text": "Store hours in Participation.", "correct": true, "why": "Hours describe a particular person–project association."}, {"text": "Store a single hours value in Project and reuse it for every participant.", "correct": false, "why": "Different people may contribute different hours to the same project."}], "explanation": "An attribute belongs where its determining identity resides; relationship-specific values cannot generally be moved to one participant.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q9", "type": "multi", "topic": "Changing review requirements", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. A new rule permits the same staff member to review the same participation several times, retaining every review.", "prompt": "Which redesigns are justified?", "options": [{"text": "The composite Participation FK should be removed because reviews repeat.", "correct": false, "why": "Repeated events still refer to a valid participation."}, {"text": "A globally unique reviewID can be the new primary key.", "correct": true, "why": "A new event identifier distinguishes repeated occurrences."}, {"text": "The old key (staffID,personID,pid) can no longer distinguish every review event.", "correct": true, "why": "Repeated reviews can now share all three old key values."}, {"text": "Adding reviewDate always creates a candidate key, even if simultaneous reviews are allowed.", "correct": false, "why": "A timestamp is a key only when uniqueness is guaranteed by the requirements."}, {"text": "A review sequence unique within each staff–participation combination can extend the old key.", "correct": true, "why": "Adding the local sequence makes each repeated event distinct."}], "explanation": "A relationship tuple and a repeatable event are different identities. Change the key while retaining the participant references.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q10", "type": "multi", "topic": "Whole research mapping audit", "scenario": "Use research scenario U. Apply the rules shown in the diagram; do not add unstated uniqueness rules. Use one table per strong/weak entity, a separate phone table, Person plus its two subtype tables, a Participation table, a Review table, and a nullable mentorID in Person. Do not introduce surrogate keys or extra relationship tables.", "prompt": "Which audit results are correct?", "options": [{"text": "The mapping has eleven referencing FK columns.", "correct": true, "why": "The ten constraints include one two-column composite FK in Review."}, {"text": "The mapping needs a separate table for binary 1:N Owns under the stated conventional mapping.", "correct": false, "why": "Owns is represented by Project.did."}, {"text": "The mapping has nine tables.", "correct": true, "why": "Department, DepartmentPhone, Project, Task, Person, Staff, Student, Participation and Review give nine."}, {"text": "The mapping has ten FK constraints.", "correct": true, "why": "Counts are 1+1+1+1+1+1+2+2 across phone, project, task, mentor, Staff, Student, Participation and Review."}, {"text": "Review contributes three FK constraints to the total.", "correct": false, "why": "Review contributes a reviewer FK and one composite participation FK."}], "explanation": "Count tables first, then each declared reference. The recursive mentor reference is easy to miss.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-research.svg"}, {"id": "p2q11", "type": "multi", "topic": "Weak ward identity", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Hospital H1 and Hospital H2 each have Ward 3.", "prompt": "Which statements preserve this situation?", "options": [{"text": "Ward has a composite key, so it needs two independent FKs to Hospital.", "correct": false, "why": "The owner reference is a single FK on hid; wardNo is the partial key, not another Hospital reference."}, {"text": "Ward.hid may be NULL for a temporary ward.", "correct": false, "why": "Every weak Ward belongs to exactly one Hospital; no temporary-owner exception is stated."}, {"text": "wardNo must be globally unique.", "correct": false, "why": "The two wards in the scenario legitimately share wardNo=3."}, {"text": "An Admission reference to a Ward must identify both its hospital and its ward number in this mapping.", "correct": true, "why": "The full referenced Ward key contains both columns."}, {"text": "Ward can use primary key (hid,wardNo).", "correct": true, "why": "Ward numbers are local to their owning hospital."}], "explanation": "Weak identity combines owner identity with the partial key. Composite primary keys do not imply multiple foreign keys.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q12", "type": "multi", "topic": "Total disjoint clinician ISA", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. The hospital imports clinician C9 and considers possible role records.", "prompt": "Which final states satisfy the stated ISA rules?", "options": [{"text": "C9 has a Doctor row and no Nurse row.", "correct": true, "why": "Exactly one role satisfies totality and disjointness."}, {"text": "C9 has neither role after the import is complete.", "correct": false, "why": "Total specialisation requires at least one role."}, {"text": "C9 has a Nurse row and no Doctor row.", "correct": true, "why": "Exactly one role satisfies both constraints."}, {"text": "C9 has both Doctor and Nurse rows.", "correct": false, "why": "Disjointness forbids simultaneous membership."}, {"text": "Another clinician can use a different role from C9.", "correct": true, "why": "The ISA rule applies to each individual, not to the entire population as one choice."}], "explanation": "Total plus disjoint means exactly one subtype for each superclass instance.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q13", "type": "multi", "topic": "Clinical ISA mapping alternatives", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. The team compares three standard representations for clinicians.", "prompt": "Which assessments are correct?", "options": [{"text": "Subtype-only tables automatically provide one universal target table for every FK to Clinician.", "correct": false, "why": "There is no retained Clinician table in that representation; generic references need additional design."}, {"text": "Subtype-only tables are possible because every clinician has a role.", "correct": true, "why": "Totality prevents superclass-only instances from being lost."}, {"text": "Parent-plus-subtype tables can represent this ISA.", "correct": true, "why": "This general approach supports the stated total/disjoint case."}, {"text": "One Clinician table with a compulsory Doctor/Nurse discriminator can represent this ISA.", "correct": true, "why": "Disjointness permits one discriminator, and totality requires a real subtype value."}, {"text": "A single-table mapping must make both specialty and grade NOT NULL for every row.", "correct": false, "why": "Each field belongs to only one subtype; irrelevant subtype fields may be NULL."}], "explanation": "A mapping can represent the ISA while making other references harder. Validity and convenience are different questions.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q14", "type": "multi", "topic": "Two roles of Doctor identifiers", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Use Clinician plus Doctor and Nurse tables. Doctor stores cid and supervisorID.", "prompt": "Which statements are correct?", "options": [{"text": "Doctor.cid is both its primary key and an FK to Clinician.cid.", "correct": true, "why": "The subtype inherits its identity from the superclass."}, {"text": "supervisorID must be UNIQUE because every doctor has at most one supervisor.", "correct": false, "why": "A scalar supervisorID already gives each doctor at most one supervisor; UNIQUE would restrict the supervisor to one supervisee."}, {"text": "supervisorID should reference Nurse.cid because Doctor and Nurse share the same superclass.", "correct": false, "why": "Shared ancestry does not change the role explicitly required for supervision."}, {"text": "Doctor.supervisorID is a separate FK to Doctor.cid.", "correct": true, "why": "The supervising person must have the Doctor role."}, {"text": "The two references count as two FK constraints.", "correct": true, "why": "The inherited identity reference and recursive supervision reference enforce different links."}], "explanation": "An inherited subtype key and a recursive relationship can use similar identifiers while representing distinct constraints.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q15", "type": "multi", "topic": "Nested weak identity", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. An Observation is identified locally inside one patient’s enrolment in one trial. Use Enrolment primary key (patientID,trialID), with no surrogate enrolment key.", "prompt": "Which conclusions follow?", "options": [{"text": "Observation needs one composite FK to Enrolment.", "correct": true, "why": "A single reference verifies the complete owner enrolment."}, {"text": "Observation can use primary key (patientID,trialID,obsNo).", "correct": true, "why": "The owner key combines with the local observation number."}, {"text": "That owner FK uses two referencing columns.", "correct": true, "why": "patientID and trialID jointly identify the owner."}, {"text": "Different enrolments may reuse obsNo=1.", "correct": true, "why": "The observation number is only unique inside its owner enrolment."}, {"text": "Separate FKs to Patient and Trial alone guarantee a valid owner enrolment.", "correct": false, "why": "A patient and trial may exist without that patient being enrolled in that trial."}], "explanation": "Follow ownership all the way to the complete owner identity; do not count composite components as separate constraints.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q16", "type": "multi", "topic": "Repeat admissions", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Patient P7 enters Ward 2 of Hospital H1 twice on different occasions. Both visits must be retained.", "prompt": "Which mapping statements are correct?", "options": [{"text": "Admission needs separate references to Patient, Ward and Doctor.", "correct": true, "why": "Each event is linked to exactly one instance of all three participant types."}, {"text": "The pair (patientID,wardNo) is necessarily a candidate key.", "correct": false, "why": "It repeats for repeated admissions and also omits the hospital part of Ward identity."}, {"text": "An Admission may omit its attending Doctor because Doctor participation has minimum zero.", "correct": false, "why": "A Doctor may attend no admissions, but each Admission requires exactly one Doctor."}, {"text": "admissionID can distinguish the two admission events.", "correct": true, "why": "The independent event key is expressly supplied."}, {"text": "These three FK constraints use four referencing columns in the specified mapping.", "correct": true, "why": "Patient and Doctor use one column each; Ward uses hid and wardNo."}], "explanation": "Read participation from both ends: an optional Doctor-to-Admission collection does not make the event’s Doctor optional.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q17", "type": "multi", "topic": "Avoiding invented constraints", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Doctor D1 belongs to Hospital H1. An Admission links D1 with a Ward in Hospital H2. All referenced rows exist.", "prompt": "Which assessments are justified by the given rules?", "options": [{"text": "The diagram does not itself require the doctor’s hospital to match the ward’s hospital.", "correct": true, "why": "No cross-hospital equality rule is stated."}, {"text": "The original diagram must be changed to make Hospital a weak entity.", "correct": false, "why": "The proposed policy concerns relationship consistency, not Hospital identity."}, {"text": "The Ward composite FK by itself checks the doctor’s Hospital assignment.", "correct": false, "why": "The Ward FK has no knowledge of the Doctor-to-Hospital relationship."}, {"text": "If the organisation later bans cross-hospital attendance, the design needs an additional constraint strategy.", "correct": true, "why": "A new business rule needs enforcement beyond the listed identity references."}, {"text": "The row necessarily violates the Admission-to-Doctor FK.", "correct": false, "why": "That FK checks the Doctor identity, which exists."}], "explanation": "A plausible real-world policy is not automatically a requirement. Test only the stated rules.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q18", "type": "multi", "topic": "Whole clinical mapping audit", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Use parent-plus-subtype ISA mapping; separate phone, Enrolment and Admission tables; conventional weak mappings; and a nullable supervisorID in Doctor. Lead-doctor and hospital-assignment 1:N relationships become FKs.", "prompt": "Which totals and qualifications are correct?", "options": [{"text": "The FK constraints use fifteen referencing columns.", "correct": true, "why": "The Observation and Admission-to-Ward FKs each add one column beyond the constraint count."}, {"text": "The mapping contains eleven tables.", "correct": true, "why": "Hospital, HospitalPhone, Ward, Clinician, Doctor, Nurse, Patient, Trial, Enrolment, Observation and Admission give eleven."}, {"text": "Additional enforcement may be needed to ensure every Hospital has at least one Ward.", "correct": true, "why": "A child-to-parent FK verifies existing children’s parents, not a parent’s minimum child count."}, {"text": "PKs and FKs alone enforce the total and disjoint clinician ISA.", "correct": false, "why": "Those constraints do not guarantee exactly one subtype row per Clinician."}, {"text": "The mapping contains thirteen FK constraints.", "correct": true, "why": "Phone1, Ward1, Clinician1, Doctor2, Nurse1, Trial1, Enrolment2, Observation1 and Admission3 total thirteen."}], "explanation": "Distinguish representational tables, identity references and constraints that require more than ordinary PK/FK declarations.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q19", "type": "multi", "topic": "Testing legal populations", "scenario": "Use clinical scenario H. Apply the rules shown in the diagram; do not add unstated constraints. Consider complete database states, not temporary states during a multi-step update.", "prompt": "Which situations can satisfy the diagram?", "options": [{"text": "A Hospital exists with no Wards.", "correct": false, "why": "Hospital participation in Contains has minimum one."}, {"text": "A Trial currently has no enrolled Patients but has its required lead Doctor.", "correct": true, "why": "Trial participation in Enrolment is optional."}, {"text": "An Observation is recorded for a Patient–Trial pair that has no Enrolment.", "correct": false, "why": "The weak Observation requires an existing owning Enrolment."}, {"text": "A Patient is not enrolled in any Trial.", "correct": true, "why": "Patient participation in Enrolment has minimum zero."}, {"text": "Two Hospitals each contain a Ward numbered 1.", "correct": true, "why": "Ward numbering is local to its Hospital."}], "explanation": "A population can be empty on an optional side while mandatory owners and minimum-one collections must still exist.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario.", "diagram": "assets/eer-clinical.svg"}, {"id": "p2q20", "type": "multi", "topic": "Ternary relationship identity", "scenario": "A supplier delivers a part to a project. For each (part,project) pair, exactly one supplier is chosen. A supplier can deliver many parts to many projects. A delivery row records quantity, and this scenario has one current row per chosen assignment.", "prompt": "Which statements are justified?", "options": [{"text": "supplierID alone necessarily determines a Delivery row.", "correct": false, "why": "A supplier may participate in many part–project assignments."}, {"text": "Delivery still needs references to Supplier, Part and Project.", "correct": true, "why": "Reducing the primary key does not remove participating entity references."}, {"text": "Three independent binary relations always preserve the exact delivery triples.", "correct": false, "why": "Pairwise associations can admit combinations that never occurred together."}, {"text": "The pair (partID,projectID) can be the Delivery primary key.", "correct": true, "why": "The stated rule makes that pair determine the chosen supplier and current assignment."}, {"text": "Adding supplierID to the chosen pair produces a superkey, but not a minimal key under the stated rule.", "correct": true, "why": "The pair already identifies the row, so supplierID is redundant for uniqueness."}], "explanation": "A ternary “one” condition can reduce the relation’s key, while all participant foreign keys remain necessary.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}, {"id": "p2q21", "type": "multi", "topic": "One-to-one participation", "scenario": "Each laboratory has exactly one safety certificate. Each certificate belongs to exactly one laboratory. A designer keeps Lab and Certificate as separate tables and stores labID in Certificate.", "prompt": "Which constraints or observations are correct?", "options": [{"text": "Those three constraints alone ensure every Lab row has a Certificate row.", "correct": false, "why": "They govern Certificate rows; they do not require a referencing row for every laboratory."}, {"text": "A UNIQUE constraint should instead be placed on certificate expiryDate to enforce the 1:1 relationship.", "correct": false, "why": "Expiry date is unrelated to the identities participating in the one-to-one association."}, {"text": "Certificate.labID should be NOT NULL.", "correct": true, "why": "Every certificate must be associated with a laboratory."}, {"text": "Certificate.labID should be UNIQUE.", "correct": true, "why": "A laboratory can have at most one certificate."}, {"text": "Certificate.labID should reference Lab.labID.", "correct": true, "why": "The laboratory must exist."}], "explanation": "FK + NOT NULL + UNIQUE enforces one side’s mandatory 1:1 reference. The inverse minimum still needs consideration.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}, {"id": "p2q22", "type": "multi", "topic": "Relationship versus event", "scenario": "A courier can transport the same parcel several times. Each transport has a globally unique tripID, departure time and fee. No rule says departure times are unique.", "prompt": "Which designs preserve these events?", "options": [{"text": "A primary key consisting only of (courierID,parcelID) would reject some permitted trips.", "correct": true, "why": "The same pair is allowed to recur."}, {"text": "The fee belongs to the transport event rather than necessarily to the Courier entity.", "correct": true, "why": "Different trips may have different fees."}, {"text": "Repeating a relationship means both entity foreign keys should be removed.", "correct": false, "why": "Every transport event must still identify its courier and parcel."}, {"text": "Transport(tripID PK,courierID FK,parcelID FK,departure,fee) is a suitable representation.", "correct": true, "why": "The event key separates repeated courier–parcel combinations."}, {"text": "A key of (courierID,parcelID,departure) is guaranteed by the stated requirements.", "correct": false, "why": "No departure-time uniqueness rule is provided."}], "explanation": "Choose identifiers from guaranteed uniqueness, not from a timestamp that merely seems likely to differ.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}, {"id": "p2q23", "type": "multi", "topic": "Composite multivalued attributes", "scenario": "A museum records several contact addresses for each donor. Each address has street, city and postcode. An identical complete address must not be repeated for the same donor, but different donors may share an address.", "prompt": "Which statements are correct?", "options": [{"text": "city alone should be UNIQUE in DonorAddress.", "correct": false, "why": "Several addresses and donors may share a city."}, {"text": "A composite primary key containing donorID and all three address components can enforce the stated duplicate rule.", "correct": true, "why": "The complete tuple distinguishes permitted donor-address values under this design."}, {"text": "A separate DonorAddress relation can contain donorID, street, city and postcode.", "correct": true, "why": "A multivalued composite attribute maps to a separate relation containing its components and owner key."}, {"text": "donorID in DonorAddress should reference Donor.", "correct": true, "why": "Each address entry belongs to an existing donor."}, {"text": "Flattening the components into one Donor row is sufficient even when the donor has many addresses.", "correct": false, "why": "One set of columns holds one address, not an arbitrary multivalued collection."}], "explanation": "Composite tells you how a value is structured; multivalued tells you that a separate set of values must be represented.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}, {"id": "p2q24", "type": "multi", "topic": "Dependence and weak entities", "scenario": "Every support ticket belongs to one customer and must be deleted if that customer is deleted. Nevertheless, each ticket receives a globally unique ticketID used independently throughout the system.", "prompt": "Which conclusions follow?", "options": [{"text": "Ticket must use a dashed-underlined partial key because it has a deletion dependency.", "correct": false, "why": "Its supplied identifier is globally unique, not merely unique within an owner."}, {"text": "customerID may still be a mandatory FK in Ticket.", "correct": true, "why": "The required ownership relationship is separate from Ticket’s independent identity."}, {"text": "The deletion policy alone does not prove that Ticket is a weak entity.", "correct": true, "why": "Existence dependence is different from lacking an independent key."}, {"text": "Every mandatory FK must be part of its table’s primary key.", "correct": false, "why": "Mandatory participation does not necessarily contribute to entity identification."}, {"text": "ticketID can be a primary key without adding customerID to it.", "correct": true, "why": "The globally unique identifier already distinguishes tickets."}], "explanation": "Identify weakness from identification rules. A strong entity can still have mandatory and deletion-dependent relationships.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}, {"id": "p2q25", "type": "multi", "topic": "Flags for total overlapping specialisation", "scenario": "An equipment item must be classified as portable, laboratory, or both. The designer uses one Equipment table with boolean isPortable and isLaboratory columns. Both flags are NOT NULL.", "prompt": "Which rules or consequences are correct?", "options": [{"text": "The state (false,false) must be rejected.", "correct": true, "why": "Total covering requires membership in at least one subtype."}, {"text": "An exclusive-or rule would correctly preserve every permitted item.", "correct": false, "why": "Exclusive-or rejects the dual-membership case that overlap permits."}, {"text": "Subtype-specific attributes may need conditional checks tied to their corresponding flags.", "correct": true, "why": "A value required only for portable items, for example, should be checked when isPortable is true."}, {"text": "The state (true,true) must remain allowed.", "correct": true, "why": "Overlap explicitly permits both classifications."}, {"text": "A rule requiring at least one flag to be true expresses the covering condition.", "correct": true, "why": "With non-null boolean flags, this rejects exactly the unclassified case."}], "explanation": "Two flags can represent overlap; totality adds an at-least-one condition rather than an exactly-one condition.", "source": "Lectures 04–05: ER/EER modelling and relational mapping; original practice scenario."}]}, {"id": 3, "title": "Design under pressure", "lectures": "06–07", "questions": [{"id": "p3q1", "type": "multi", "topic": "Anomalies", "scenario": "A consultancy stores Staff(staffID, staffName, deptID, deptName, office). staffID is the primary key. Every department has one name and office, and each staff member belongs to one department. Departments may exist before hiring anyone.", "prompt": "Which problems or design conclusions are justified?", "options": [{"text": "Making staffName UNIQUE removes the dependency deptID → office.", "correct": false, "why": "Uniqueness of names does not change the department rule."}, {"text": "Deleting the last staff row of a department can remove the only stored record of its office.", "correct": true, "why": "The office fact is stored only in staff rows."}, {"text": "Separating Department(deptID, deptName, office) allows departments to be stored independently.", "correct": true, "why": "The department now has its own row and key."}, {"text": "Changing a department office may require updating several rows.", "correct": true, "why": "Each staff row repeats that department fact."}, {"text": "A new department with no staff can always be represented by a row whose staffID is NULL.", "correct": false, "why": "The primary key cannot be NULL."}], "explanation": "Identify which real-world fact is repeated and whether that fact can exist without a staff member.", "source": "Lecture 06, slides 4–10"}, {"id": "p3q2", "type": "multi", "topic": "Closure and minimal keys", "scenario": "A booking system has R(A,B,C,D,E). A is a booking code, B a customer code, C a route code, D a zone, and E a confirmation code. Its complete FD basis is A→BC, B→D, CD→E, E→A. No additional independent dependencies are assumed.", "prompt": "Which sets are candidate keys?", "options": [{"text": "ABC", "correct": false, "why": "It is a superkey but contains the smaller key A."}, {"text": "B", "correct": false, "why": "B gives D only; C and the remaining attributes are missing."}, {"text": "E", "correct": true, "why": "E gives A, which gives every attribute."}, {"text": "CD", "correct": true, "why": "CD gives E, then A and B; neither C nor D alone suffices."}, {"text": "A", "correct": true, "why": "A gives B,C, then D, then E; a singleton is minimal."}], "explanation": "Closure establishes a superkey; removal of each attribute tests minimality. BC is another candidate key, although it is not listed.", "source": "Lecture 06, slides 14–18"}, {"id": "p3q3", "type": "multi", "topic": "Superkeys versus keys", "scenario": "For Parcel(P,Q,R,S), the complete FD basis is P→Q and Q→RS. A student computes (PQ)+={P,Q,R,S} and declares PQ to be a candidate key.", "prompt": "Which parts of the review are valid?", "options": [{"text": "P is a candidate key.", "correct": true, "why": "P determines all attributes and has no proper nonempty subset."}, {"text": "Removing Q still leaves a superkey.", "correct": true, "why": "P determines Q, then R and S."}, {"text": "PQ is a superkey.", "correct": true, "why": "Its closure contains all four attributes."}, {"text": "PQ is minimal because its closure contains every attribute.", "correct": false, "why": "Closure alone does not prove minimality."}, {"text": "Q is not a superkey under the stated dependencies.", "correct": true, "why": "Q gives R and S but cannot determine P."}], "explanation": "Do not equate “determines all attributes” with “minimal determinant”.", "source": "Lecture 06, slides 14–18"}, {"id": "p3q4", "type": "multi", "topic": "Inference from sample rows", "scenario": "A supplier register currently contains (city,postcode): (Kandy,20000), (Galle,80000), (Matara,81000). The analyst proposes city→postcode. The business has not stated such a rule.", "prompt": "Which conclusions are justified?", "options": [{"text": "Adding (Kandy,20001) would violate the proposed dependency.", "correct": true, "why": "It creates equal city values with different postcodes."}, {"text": "The proposed dependency automatically implies postcode→city.", "correct": false, "why": "An FD does not automatically work in reverse."}, {"text": "These three rows satisfy city→postcode.", "correct": true, "why": "There is no pair with equal city and different postcode."}, {"text": "The present sample is enough to choose city as a guaranteed key for all future data.", "correct": false, "why": "The required uniqueness rule has not been established."}, {"text": "These rows prove that city→postcode must hold in every future legal instance.", "correct": false, "why": "A finite sample cannot establish an unstated business dependency."}], "explanation": "Distinguish an FD holding in one instance from an FD that constrains all legal instances.", "source": "Lecture 06, slides 11–14"}, {"id": "p3q5", "type": "multi", "topic": "Armstrong reasoning", "scenario": "A shipment relation Shipment(OrderID,CustomerID,Region,ShipDate,PackageNo) uses the complete dependency basis OrderID→CustomerID, CustomerID→Region, and OrderID→ShipDate. A developer wants to derive constraints without inspecting sample values.", "prompt": "Which dependency claims are justified?", "options": [{"text": "CustomerID→OrderID", "correct": false, "why": "Nothing determines OrderID from CustomerID."}, {"text": "OrderID,PackageNo→Region,PackageNo", "correct": true, "why": "Augment OrderID→Region with PackageNo."}, {"text": "Region→CustomerID cannot be derived from this dependency basis.", "correct": true, "why": "No dependency permits reconstructing CustomerID from Region."}, {"text": "OrderID→CustomerID,Region,ShipDate", "correct": true, "why": "Combine the given and derived dependencies by union."}, {"text": "OrderID→Region", "correct": true, "why": "Apply transitivity through CustomerID."}], "explanation": "Use transitivity, union and augmentation; never reverse a dependency merely because it looks useful.", "source": "Lecture 06, slides 15–17"}, {"id": "p3q6", "type": "multi", "topic": "Partial dependencies", "scenario": "An equipment hire relation Hire(memberID, itemID, memberName, itemName, hours) has key (memberID,itemID). Its complete FD basis is memberID→memberName, itemID→itemName, and (memberID,itemID)→hours. All values are atomic.", "prompt": "Which judgments are correct?", "options": [{"text": "The relation violates 2NF.", "correct": true, "why": "Two non-prime attributes depend on proper parts of its key."}, {"text": "Choosing memberID as the primary key would be a valid repair without changing the business rules.", "correct": false, "why": "A member can have multiple items; memberID does not determine all attributes."}, {"text": "hours is necessarily partially dependent on the key.", "correct": false, "why": "No proper subset of the key determines hours under the stated basis."}, {"text": "hours is prime because the whole candidate key determines it.", "correct": false, "why": "Being determined by a key does not make an attribute prime; it must occur in a candidate key."}, {"text": "Member(memberID,memberName), Item(itemID,itemName), Hire(memberID,itemID,hours) removes the stated partial dependencies.", "correct": true, "why": "Each descriptive fact moves to the relation identified by its determinant."}], "explanation": "Separate facts about a member, an item, and the pairing of the two.", "source": "Lecture 06, slides 20–22"}, {"id": "p3q7", "type": "multi", "topic": "Alternate candidate keys", "scenario": "A 1NF relation R(A,B,C,D) has complete FD basis A→BCD, BC→A, B→D. The designer chooses A as its primary key and argues that a single-column primary key guarantees 2NF.", "prompt": "Which statements are correct?", "options": [{"text": "D is non-prime.", "correct": true, "why": "The candidate keys are A and BC, neither containing D."}, {"text": "B→D is a partial dependency on candidate key BC.", "correct": true, "why": "B is a proper subset of BC and D is non-prime."}, {"text": "BC is an alternate candidate key.", "correct": true, "why": "BC gives A and hence all attributes; neither B nor C alone does."}, {"text": "The relation is in 2NF because the chosen primary key has one column.", "correct": false, "why": "2NF must consider every candidate key, not just the chosen primary key."}, {"text": "The 2NF violation persists if BC is chosen as primary key instead.", "correct": true, "why": "The dependencies and all candidate keys stay the same when a different key is designated primary."}], "explanation": "A hidden composite alternate key can expose a partial dependency even when the primary key is simple.", "source": "Lecture 06, slides 18–23"}, {"id": "p3q8", "type": "multi", "topic": "Highest normal form", "scenario": "An appointment relation R(appointmentID, doctorID, specialty) has complete FD basis appointmentID→doctorID and doctorID→specialty. Values are atomic and no other independent FDs hold.", "prompt": "Which conclusions about this schema are correct?", "options": [{"text": "3NF but not BCNF", "correct": false, "why": "The non-prime dependency doctorID→specialty violates 3NF as well."}, {"text": "BCNF", "correct": false, "why": "doctorID does not determine appointmentID."}, {"text": "doctorID determines appointmentID under the stated dependencies.", "correct": false, "why": "The dependency basis gives no route from doctorID back to appointmentID."}, {"text": "2NF but not 3NF", "correct": true, "why": "doctorID is a non-superkey determinant of non-prime specialty."}, {"text": "appointmentID is a candidate key.", "correct": true, "why": "It determines doctorID and then specialty; no smaller nonempty determinant exists."}], "explanation": "Follow appointmentID→doctorID→specialty. The transitive non-key fact causes the 3NF failure.", "source": "Lecture 06, slides 21–25"}, {"id": "p3q9", "type": "multi", "topic": "Lossless decomposition", "scenario": "A project assignment relation R(staffID, projectID, desk) has complete FD basis staffID→projectID,desk. A proposed split stores S(staffID,projectID) and T(projectID,desk). Projects may have multiple staff using different desks.", "prompt": "Which conclusions are valid?", "options": [{"text": "Retaining every original attribute is sufficient to guarantee losslessness.", "correct": false, "why": "The projections can preserve every attribute while losing the association between staffID and desk."}, {"text": "Splitting into S(staffID,projectID) and U(staffID,desk) is lossless under the stated FD.", "correct": true, "why": "The shared staffID determines both components."}, {"text": "The shared projectID alone proves the split is lossless.", "correct": false, "why": "The intersection must determine at least one complete component, not merely exist."}, {"text": "The original FD staffID→desk is directly enforceable using only S and T separately under their projected FDs.", "correct": false, "why": "Neither component includes both staffID and desk, and the projected dependencies cannot recover it."}, {"text": "Joining the projections can associate a staff member with another staff member’s desk.", "correct": true, "why": "Two desks for the same project match each staff row for that project."}], "explanation": "For example, (s1,p1,d1) and (s2,p1,d2) generate two extra combinations under the proposed split.", "source": "Lecture 06, slides 8–10, 14–18"}, {"id": "p3q10", "type": "multi", "topic": "BCNF versus dependency preservation", "scenario": "A course allocation relation R(student,course,tutor) has complete FD basis (student,course)→tutor and tutor→course. Tutors may teach many students but exactly one course. All values are atomic.", "prompt": "Which statements are correct?", "options": [{"text": "The split TutorCourse(tutor,course), StudentTutor(student,tutor) is lossless.", "correct": true, "why": "The intersection tutor determines TutorCourse."}, {"text": "That split preserves (student,course)→tutor using component constraints alone.", "correct": false, "why": "Two tutors for one student may map to the same course without violating either component FD."}, {"text": "tutor→course violates BCNF.", "correct": true, "why": "A tutor does not determine student and therefore is not a superkey."}, {"text": "The original relation is in 3NF under these dependencies.", "correct": true, "why": "All three attributes are prime; the non-superkey determinant tutor has prime course on the right-hand side."}, {"text": "The candidate keys are (student,course) and (student,tutor).", "correct": true, "why": "Each pair determines the third attribute, and each is minimal."}], "explanation": "Lossless BCNF decomposition can sacrifice dependency preservation. This relation is a classic 3NF-but-not-BCNF case.", "source": "Lecture 06, slides 18–25"}, {"id": "p3q11", "type": "multi", "topic": "Choosing a decomposition", "scenario": "Warehouse R(binID, zoneID, zoneName, supervisor) has complete FD basis binID→zoneID and zoneID→zoneName,supervisor. A team replaces it with Bin(binID,zoneID) and Zone(zoneID,zoneName,supervisor).", "prompt": "Which claims hold under these dependencies?", "options": [{"text": "A zone without any bin still cannot be represented after the split.", "correct": false, "why": "The separate Zone table allows an independent zone row, regardless of Bin rows."}, {"text": "Zone remains outside BCNF solely because it contains three attributes.", "correct": false, "why": "Attribute count does not determine a normal form; zoneID is its key."}, {"text": "The split is lossless.", "correct": true, "why": "Shared zoneID determines the Zone relation."}, {"text": "The original dependencies can be enforced within the two component relations.", "correct": true, "why": "binID→zoneID is local to Bin; the other dependencies are local to Zone."}, {"text": "The split requires duplicating zoneName once for every bin.", "correct": false, "why": "zoneName is stored once per zone rather than repeated in Bin."}], "explanation": "A useful decomposition separates the zone fact, preserves the dependencies and reconstructs the original bin facts.", "source": "Lecture 06, slides 7–10, 23–25"}, {"id": "p3q12", "type": "multi", "topic": "Data-dependent evidence", "scenario": "A migration team tests a decomposition R(A,B,C)→R1(A,B), R2(B,C). Its complete FD basis is {A→B}. Their current one-row dataset rejoins perfectly.", "prompt": "Which assessments are sound?", "options": [{"text": "The shared attribute B determines neither complete component under the declared FD.", "correct": true, "why": "B does not determine A or C, so the binary lossless criterion fails."}, {"text": "B is known to determine R1.", "correct": false, "why": "B→A is not implied by A→B."}, {"text": "The decomposition is guaranteed lossless because A is in one component.", "correct": false, "why": "Merely keeping the determinant somewhere is not the binary lossless criterion."}, {"text": "Two legal rows (a1,b1,c1) and (a2,b1,c2) provide a counterexample.", "correct": true, "why": "Their projections rejoin into four tuples, adding cross-pairings."}, {"text": "The successful one-row test proves losslessness for all legal data.", "correct": false, "why": "A small instance can hide spurious-tuple behaviour."}], "explanation": "The lossless property must hold for every legal instance, not just the test data.", "source": "Lecture 06, slides 8–10, 15–18"}, {"id": "p3q13", "type": "multi", "topic": "Views and current data", "scenario": "A payroll team defines ordinary view PublicStaff as SELECT eid,ename FROM Employee. Users are granted SELECT on the view but not on Employee. Assume permissions are configured so access through the view works.", "prompt": "Which conclusions are correct?", "options": [{"text": "A query against PublicStaff can add its own WHERE condition.", "correct": true, "why": "A view can be queried similarly to a table."}, {"text": "The view can hide the salary column from these users.", "correct": true, "why": "salary is not exposed and direct base-table access was denied by assumption."}, {"text": "The view necessarily stores a separate copy of every selected row.", "correct": false, "why": "This is an ordinary, non-materialized view."}, {"text": "Dropping PublicStaff also deletes Employee rows.", "correct": false, "why": "Dropping the view removes the view definition, not base data."}, {"text": "Adding a committed Employee row can make that row appear in the view without recreating it.", "correct": true, "why": "An ordinary view represents its defining query, not a frozen copy."}], "explanation": "Distinguish a stored query definition from stored copies of query results.", "source": "Lecture 07, slides 4–10"}, {"id": "p3q14", "type": "multi", "topic": "Aggregate view edits", "scenario": "A team creates WorkSummary(eid,totalPct) by grouping Works(eid,did,pct) and calculating SUM(pct). An employee currently has assignments of 40 and 30. The interface tries UPDATE WorkSummary SET totalPct=90 WHERE eid=7. No INSTEAD OF trigger is defined.", "prompt": "Which reviews are justified?", "options": [{"text": "SUM(pct) is directly updatable as if it were an ordinary base column.", "correct": false, "why": "The aggregate expression is not a directly updatable column."}, {"text": "SQL Server will automatically add 20 to the largest assignment.", "correct": false, "why": "No such allocation rule is defined by an aggregate view."}, {"text": "A procedure can explicitly implement a chosen allocation rule on Works.", "correct": true, "why": "The business decision can be programmed rather than inferred from SUM."}, {"text": "The view remains useful for reading totals even if that UPDATE is rejected.", "correct": true, "why": "Read usefulness and updateability are different properties."}, {"text": "The requested total does not uniquely specify which underlying assignment should change.", "correct": true, "why": "Possible allocations include 60+30, 40+50 and many others."}], "explanation": "An aggregate value is a result of many rows; changing it requires a defined rule for changing those rows.", "source": "Lecture 07, slides 6–10, 24–28"}, {"id": "p3q15", "type": "multi", "topic": "IF boundary and NULL", "scenario": "A service prints a staffing message using the following code. Run A assigns @n=1000; run B leaves @n unassigned. No other statements alter @n.", "prompt": "Which statements describe the executions?", "options": [{"text": "The unassigned variable in run B holds NULL.", "correct": true, "why": "A local variable declared without an initializer starts as NULL."}, {"text": "The ELSE message is logically accurate for run A.", "correct": false, "why": "Exactly 1000 is not fewer than 1000."}, {"text": "Changing the ELSE message to “Not known to be above 1000” fits both runs.", "correct": true, "why": "It covers both false and unknown conditions."}, {"text": "Run B prints the ELSE message.", "correct": true, "why": "NULL>1000 is unknown; IF does not treat it as true."}, {"text": "Run A prints the ELSE message.", "correct": true, "why": "1000>1000 is false."}], "explanation": "ELSE is reached when the condition is not true; that includes equality and unknown values.", "source": "Lecture 07, slides 12–15", "code": "DECLARE @n int;\n-- Run A only: SET @n=1000;\nIF @n>1000 PRINT 'Above 1000';\nELSE PRINT 'Fewer than 1000';"}, {"id": "p3q16", "type": "multi", "topic": "Loop trace", "scenario": "A report routine uses a counter to skip one record and stop before processing a later record. No statements outside this code execute.", "prompt": "Which statements are correct?", "options": [{"text": "BREAK prevents every later statement in the entire SQL batch from running.", "correct": false, "why": "BREAK exits the innermost loop, not the entire batch."}, {"text": "The printed sequence is 1, 3, 4.", "correct": true, "why": "2 reaches CONTINUE; 5 reaches BREAK before PRINT."}, {"text": "Moving the increment after CONTINUE can cause the loop to become stuck at 2.", "correct": true, "why": "Once @i becomes 2, the skip would prevent future increments."}, {"text": "CONTINUE exits the WHILE permanently.", "correct": false, "why": "CONTINUE starts the next iteration; BREAK exits."}, {"text": "The final value of @i is 5.", "correct": true, "why": "The increment to 5 occurs before the BREAK test."}], "explanation": "Trace the increment, skip condition and stop condition in their actual order.", "source": "Lecture 07, slides 16–18", "code": "DECLARE @i int=0;\nWHILE @i<6\nBEGIN\n SET @i=@i+1;\n IF @i=2 CONTINUE;\n IF @i=5 BREAK;\n PRINT @i;\nEND;"}, {"id": "p3q17", "type": "multi", "topic": "Scalar functions and empty input", "scenario": "A scalar function for a member’s unpaid total assigns @v=SUM(amount) from Fine WHERE mid=@mid AND status='Due', then returns @v. amount is NOT NULL. Member 8 has no qualifying rows. The required result is zero.", "prompt": "Which changes or observations are correct?", "options": [{"text": "Replacing SUM(amount) with COUNT(*) implements the same total for all members.", "correct": false, "why": "COUNT measures rows, not money."}, {"text": "The current SUM result for member 8 is NULL.", "correct": true, "why": "SUM over an empty input yields NULL."}, {"text": "Assigning @v=0 before the SELECT is sufficient even if SELECT still assigns SUM(amount).", "correct": false, "why": "The aggregate SELECT returns one row containing NULL and overwrites the initial value."}, {"text": "The function can be used in SELECT dbo.fnDue(8) when defined with that name and scalar return type.", "correct": true, "why": "A scalar UDF can be invoked in an expression."}, {"text": "COALESCE(SUM(amount),0) meets the empty-input requirement.", "correct": true, "why": "It replaces the empty aggregate result with zero."}], "explanation": "An aggregate SELECT without GROUP BY still produces an aggregate result row on empty input.", "source": "Lecture 07, slides 20–23"}, {"id": "p3q18", "type": "multi", "topic": "OUTPUT parameters", "scenario": "dbo.GetRange declares @dept int, @lo decimal(10,2) OUTPUT, @hi decimal(10,2) OUTPUT. It assigns salary minimum and maximum. Department 4 contains salaries 900 and 1400. The caller executes the code below.", "prompt": "Which caller-side facts are correct?", "options": [{"text": "@low remains -1.", "correct": true, "why": "Its initial caller value is unchanged when OUTPUT is omitted at the call."}, {"text": "@high becomes 1400.", "correct": true, "why": "The parameter and call both specify OUTPUT."}, {"text": "Adding OUTPUT after @low in the EXEC call allows the minimum to be copied back.", "correct": true, "why": "Output direction must be requested at the call as well."}, {"text": "The procedure RETURN status automatically contains the maximum salary.", "correct": false, "why": "RETURN status and output parameters are separate channels."}, {"text": "@low becomes 900.", "correct": false, "why": "The call omitted OUTPUT for that argument, so the changed value is not copied back."}], "explanation": "A procedure can run successfully while one caller variable remains unchanged because OUTPUT was omitted.", "source": "Lecture 07, slides 26–28", "code": "DECLARE @low decimal(10,2)=-1, @high decimal(10,2)=-1;\nEXEC dbo.GetRange @dept=4,@lo=@low,@hi=@high OUTPUT;"}, {"id": "p3q19", "type": "multi", "topic": "Percentage procedure", "scenario": "Salary is decimal(10,2), currently 1000 for one employee. A procedure parameter @pct is int and the intended increase is 10 percent. The body uses SET salary=salary+salary*(@pct/100). Assume arithmetic is ordinary SQL Server T-SQL and no triggers alter the result.", "prompt": "Which statements are valid?", "options": [{"text": "Calling the current procedure ten times with @pct=10 will eventually increase salary.", "correct": false, "why": "Each call again adds zero."}, {"text": "Using @pct/100.0 avoids the integer-division problem.", "correct": true, "why": "The decimal divisor gives a fractional percentage."}, {"text": "Passing @pct=10 produces salary 1100 with the current expression.", "correct": false, "why": "Integer division calculates 10/100 as zero."}, {"text": "With the current expression and @pct=10, salary remains 1000.", "correct": true, "why": "The computed addition is 1000*0."}, {"text": "Changing the parameter to decimal(5,2) is another valid repair for this example.", "correct": true, "why": "Decimal division preserves 0.10."}], "explanation": "Check the types inside a subexpression before considering the type of the final assignment.", "source": "Lecture 07, slides 12–14, 24–25"}, {"id": "p3q20", "type": "multi", "topic": "Trigger granularity", "scenario": "Account has two rows: (1,100), (2,200). An AFTER UPDATE trigger declares scalar @id and @b, assigns SELECT @id=accountNo,@b=balance FROM inserted, then inserts one audit row using those variables. One UPDATE statement increases both balances by 10.", "prompt": "Which findings are correct?", "options": [{"text": "The scalar assignment is a reliable way to audit both accounts.", "correct": false, "why": "A scalar pair cannot represent two affected rows."}, {"text": "INSERT INTO AccountAudit(accountNo,balance) SELECT accountNo,balance FROM inserted records both new balances.", "correct": true, "why": "The set-based INSERT processes all affected rows."}, {"text": "The trigger is guaranteed to run once for account 1 and once for account 2.", "correct": false, "why": "SQL Server DML triggers fire per statement, not separately per affected row."}, {"text": "Without ORDER BY, the scalar assignment is guaranteed to choose the lowest accountNo.", "correct": false, "why": "There is no guaranteed row ordering or guaranteed choice of lowest account."}, {"text": "inserted contains both new account rows.", "correct": true, "why": "The statement affects two rows, so both appear in inserted."}], "explanation": "The lecture’s scalar audit pattern must be repaired for statements affecting several rows.", "source": "Lecture 07, slides 29–37"}, {"id": "p3q21", "type": "multi", "topic": "Old versus new state", "scenario": "A single UPDATE moves two Fine rows from member 1 to member 2 and changes their amounts. An AFTER UPDATE trigger must recalculate both members’ stored balances from current Fine rows. No concurrent transaction is involved.", "prompt": "Which design choices or observations are correct?", "options": [{"text": "Recalculate member IDs from SELECT mid FROM inserted UNION SELECT mid FROM deleted.", "correct": true, "why": "The union identifies both old and new owners without duplicates."}, {"text": "A recalculation must handle member 1 having no remaining fines by setting its balance to zero.", "correct": true, "why": "Otherwise a stale nonzero balance may remain."}, {"text": "deleted contains the old member IDs and amounts.", "correct": true, "why": "For UPDATE, deleted preserves the pre-update row images."}, {"text": "Recalculate only member IDs from inserted.", "correct": false, "why": "This misses the old owner, member 1."}, {"text": "inserted contains the new member IDs and amounts.", "correct": true, "why": "It represents post-update rows."}], "explanation": "An update can change both the amount and the grouping key; maintain every group touched by either version.", "source": "Lecture 07, slides 31–37"}, {"id": "p3q22", "type": "multi", "topic": "Multirow business rule", "scenario": "Works(eid,did) has a composite primary key. An employee may work in at most two departments. Before an INSERT, employee 7 works in one department. A single statement inserts two further distinct departments for employee 7. An AFTER INSERT trigger tests the rule.", "prompt": "Which checks are appropriate?", "options": [{"text": "The primary key alone prevents employee 7 from gaining a third distinct department.", "correct": false, "why": "The key prevents duplicate pairs, not a maximum number of pairs."}, {"text": "Check every distinct employee in inserted rather than assigning one employee to a scalar variable.", "correct": true, "why": "One statement can affect several employees."}, {"text": "The trigger should accept the statement because each inserted row is individually valid.", "correct": false, "why": "The business rule constrains the combined set, not a single row."}, {"text": "Count only rows in inserted and reject when that count exceeds two.", "correct": false, "why": "Two new rows plus one existing row violate the rule although inserted contains only two."}, {"text": "Group the current Works rows for affected employee IDs and reject any COUNT(*)>2.", "correct": true, "why": "Current base-table rows in an AFTER trigger include the inserted assignments."}], "explanation": "A set-level limit requires counting persisted state after the whole statement and checking all affected owners.", "source": "Lecture 07, slides 29–38"}, {"id": "p3q23", "type": "multi", "topic": "AFTER versus INSTEAD OF", "scenario": "A read-facing joined view is deliberately not directly updatable for the requested operation. The team wants a trigger to translate an attempted INSERT on that view into explicitly chosen inserts on base tables.", "prompt": "Which statements are correct?", "options": [{"text": "The base inserts must be performed by the replacement logic if they are required.", "correct": true, "why": "INSTEAD OF does not automatically perform the original operation afterward."}, {"text": "The trigger still needs to consider multiple rows in inserted.", "correct": true, "why": "The attempted statement can supply several rows."}, {"text": "Defining an INSTEAD OF trigger makes all integrity constraints on base tables irrelevant.", "correct": false, "why": "Base-table writes made by the trigger still encounter their constraints."}, {"text": "An INSTEAD OF INSERT trigger can implement that translation.", "correct": true, "why": "It replaces the attempted operation with defined trigger logic."}, {"text": "An AFTER INSERT trigger on the view is the correct SQL Server mechanism.", "correct": false, "why": "SQL Server does not support AFTER DML triggers on views."}], "explanation": "Choose replacement behaviour, then explicitly implement the underlying changes while respecting base-table integrity.", "source": "Lecture 07, slides 31–35"}, {"id": "p3q24", "type": "multi", "topic": "Audit state after DELETE", "scenario": "AccountAudit(accountNo,oldBalance) must record the values removed by a DELETE statement. The trigger is AFTER DELETE, and the statement may delete many rows.", "prompt": "Which audit statements or design decisions are correct?", "options": [{"text": "The audit should use the old balances from deleted, rather than current rows from Account.", "correct": true, "why": "The deleted rows are absent from the current base table; deleted preserves their pre-delete values."}, {"text": "INSERT INTO AccountAudit SELECT accountNo,balance FROM inserted;", "correct": false, "why": "inserted has no deleted-row images for a DELETE event."}, {"text": "INSERT INTO AccountAudit(accountNo,oldBalance) SELECT accountNo,balance FROM deleted;", "correct": true, "why": "deleted contains the pre-delete image of every removed row."}, {"text": "The audit must handle all rows in deleted even when one DELETE statement removes many accounts.", "correct": true, "why": "The trigger fires for the statement and deleted can contain many rows."}, {"text": "INSERT INTO AccountAudit(accountNo,oldBalance) SELECT accountNo,balance FROM Account;", "correct": false, "why": "The removed rows are no longer in Account, and this would audit remaining accounts."}], "explanation": "For a DELETE audit, use a set-based INSERT…SELECT from deleted.", "source": "Lecture 07, slides 34–37"}, {"id": "p3q25", "type": "multi", "topic": "Two-sided business rule enforcement", "scenario": "Employee(eid,salary,did) and Department(did,managerID) support a rule: every non-manager employee must earn no more than their department manager. Each department has an existing manager. A trigger on Employee checks only rows whose salary just increased against their current managers.", "prompt": "Which changes can expose a gap, or correctly address gaps, in this trigger design?", "options": [{"text": "Changing Department.managerID to an employee with a lower salary.", "correct": true, "why": "The relevant manager relationship changes in another table."}, {"text": "Changing an employee’s did to a department with a lower-paid manager without increasing the employee salary.", "correct": true, "why": "The comparison target changes even though salary does not increase."}, {"text": "Lowering a manager’s salary below an existing subordinate’s salary.", "correct": true, "why": "The subordinate row need not be updated, and an increase-only trigger misses the manager reduction."}, {"text": "Checking every rule-changing operation, including affected departments and employees, can close these gaps.", "correct": true, "why": "The rule depends on more than one column, row and table."}, {"text": "Increasing a subordinate’s salary above the unchanged current manager salary, if that row is properly checked.", "correct": false, "why": "That is exactly the case the stated check handles."}], "explanation": "A cross-row rule must be maintained when either side of the comparison or the connecting relationship changes.", "source": "Lecture 07, slides 29, 38–40"}]}, {"id": 4, "title": "Relations, replicas & model choices", "lectures": "08–09", "questions": [{"id": "p4q1", "type": "multi", "topic": "Projection and identity", "scenario": "A training centre stores Enrolment(student, course, campus) as a mathematical relation. Its tuples are (A,SQL,North), (B,SQL,North), (C,AI,South), (D,SQL,South). An analyst projects only course and campus.", "prompt": "Which conclusions follow under relational-algebra set semantics?", "options": [{"text": "The projection preserves enough information to count students in every course-campus group.", "correct": false, "why": "Projection removes student identity and duplicate projected tuples; the North SQL student count is lost."}, {"text": "Projecting campus alone produces two tuples.", "correct": true, "why": "Only North and South remain, each once."}, {"text": "The two North SQL records collapse because the projected course-campus values are identical.", "correct": true, "why": "Set projection removes the student attribute and then deduplicates the remaining tuples."}, {"text": "The result has degree two.", "correct": true, "why": "Degree counts attributes, and the projection retains course and campus."}, {"text": "The projection contains three tuples.", "correct": true, "why": "The two distinct students in SQL at North collapse into one projected tuple."}], "explanation": "Projection changes the attributes and removes duplicate resulting tuples. Distinct original tuples need not remain distinct after projection.", "source": "L08 slides 6, 11"}, {"id": "p4q2", "type": "multi", "topic": "Selection and projection order", "scenario": "A company needs the names of employees with salary at least 40000. EMP has attributes (eid, name, salary, dept). A developer tries to move operations earlier to reduce intermediate results.", "prompt": "Which transformations are valid for every EMP instance?", "options": [{"text": "Replacing ≥40000 with >40000 preserves the answer in every database.", "correct": false, "why": "An employee earning exactly 40000 is a counterexample."}, {"text": "π_name(σ_salary≥40000(EMP)) answers the request.", "correct": true, "why": "The salary condition is evaluated before salary is discarded."}, {"text": "σ_salary≥40000(π_name(EMP)) is valid because salary still exists in the source table.", "correct": false, "why": "The selection receives only the intermediate relation, where salary is absent."}, {"text": "π_name(σ_salary≥40000(π_salary(EMP))) answers the request.", "correct": false, "why": "The inner projection removes name, so the final projection cannot recover it."}, {"text": "Selecting dept=5 and then salary≥40000 is equivalent to selecting their conjunction.", "correct": true, "why": "Both selections retain exactly tuples satisfying both predicates."}], "explanation": "An operator can use only attributes available in its input relation. Selection can be pushed below projection only when its required attributes remain available.", "source": "L08 slides 6–9"}, {"id": "p4q3", "type": "multi", "topic": "Union compatibility", "scenario": "An outreach team wants one relation of recipient identifiers and email addresses. R(id:int,email:text) is compatible with S(code:int,address:text) after renaming. T(email:text,id:int) uses the reverse order.", "prompt": "Which proposed operations are justified?", "options": [{"text": "Reordering T to (id,email) can make it union-compatible with R.", "correct": true, "why": "The same attributes can be placed in matching domain order."}, {"text": "R − S requires union compatibility just as R ∪ S does.", "correct": true, "why": "Set difference also compares complete tuples over aligned schemas."}, {"text": "Matching relation cardinalities are required before a union.", "correct": false, "why": "The numbers of tuples may differ; compatibility concerns the attribute structure."}, {"text": "R ∪ S is valid after aligning attribute names and retains each complete recipient tuple once.", "correct": true, "why": "Their corresponding domains and degree match; union uses set semantics."}, {"text": "R ∪ T is valid merely because both have two attributes.", "correct": false, "why": "Corresponding positions must also have compatible domains; here int is paired with text."}], "explanation": "Union compatibility is about degree and corresponding domains, not row counts or merely having similarly named fields.", "source": "L08 slides 11–14"}, {"id": "p4q4", "type": "multi", "topic": "Difference direction", "scenario": "A library compares registered workshop members A={1,2,3,4} with members who paid B={2,4,5}. Both relations have one integer member-id attribute.", "prompt": "Which results or interpretations are correct?", "options": [{"text": "A − B = {1,3}.", "correct": true, "why": "These are registered members absent from the paid set."}, {"text": "B − A = {1,3}.", "correct": false, "why": "The reverse difference is {5}, a paid identifier absent from registration."}, {"text": "A ∩ B = {2,4}.", "correct": true, "why": "These identifiers occur in both sets."}, {"text": "A ∪ B has seven tuples because the input cardinalities are four and three.", "correct": false, "why": "Union removes duplicate identifiers 2 and 4, giving five tuples."}, {"text": "(A − B) ∩ (B − A) identifies identifiers present in exactly one list.", "correct": false, "why": "The directional differences are disjoint, so their intersection is empty; their union is needed."}], "explanation": "Write out complete tuple membership before applying a set operation. Difference is directional; union is not bag concatenation.", "source": "L08 slides 12–14"}, {"id": "p4q5", "type": "multi", "topic": "Natural join with extra common attributes", "scenario": "A delivery firm stores Parcel(pid, depot, status) and Depot(depot, status, manager). Parcel.status describes delivery progress; Depot.status describes whether the depot is open. The intended match is only by depot.", "prompt": "Which statements are correct?", "options": [{"text": "Renaming Depot.status before the natural join can remove the accidental status match.", "correct": true, "why": "After renaming, depot is the only common attribute name."}, {"text": "Natural join must return more tuples than an equijoin on depot alone.", "correct": false, "why": "Its additional equality restriction can reduce the result; it cannot add matches."}, {"text": "A natural join automatically understands that the two status attributes have different meanings.", "correct": false, "why": "Natural join uses matching attribute names, not business meanings."}, {"text": "A natural join may discard a parcel whose depot exists but whose status text differs from Depot.status.", "correct": true, "why": "It requires equality on every common attribute, including status."}, {"text": "An explicit equijoin on Parcel.depot=Depot.depot avoids the unintended status condition.", "correct": true, "why": "The equality predicate can be limited to the intended linking attribute."}], "explanation": "Natural join is convenient only when every shared attribute name really denotes a required equality condition.", "source": "L08 slides 16–17"}, {"id": "p4q6", "type": "multi", "topic": "Cartesian product and join cardinality", "scenario": "Three tutors T(tid, speciality) and four rooms R(rid, speciality) have distinct keys. Two tutors specialise in DB and one in AI; three rooms support DB and one supports AI. The planner joins on speciality.", "prompt": "Which statements follow?", "options": [{"text": "The speciality equijoin contains seven tuples.", "correct": true, "why": "DB contributes 2×3=6 pairs, and AI contributes 1×1=1."}, {"text": "The equijoin must contain three tuples because there are three tutors.", "correct": false, "why": "One tutor can match multiple rooms; the join is not restricted to one match per tutor."}, {"text": "σ_T.speciality=R.speciality(T × R) gives the same matched pairs as the equijoin.", "correct": true, "why": "An equijoin is the corresponding equality selection over the Cartesian product."}, {"text": "Changing the names of tid and rid to the same name makes a natural join equivalent to the requested join.", "correct": false, "why": "That introduces an unintended key-equality requirement, rather than expressing speciality matching."}, {"text": "T × R contains twelve tuples.", "correct": true, "why": "Every one of three tutors is paired with every one of four rooms."}], "explanation": "Count matching pairs, not participating entities. Shared join values can generate several tuples per original row.", "source": "L08 slides 15–17"}, {"id": "p4q7", "type": "multi", "topic": "Outer-join result reasoning", "scenario": "For a staffing report, Employee(eid,dept)={(1,A),(2,A),(3,B)} and Department(dept,manager)={(A,Maya),(C,Nila)}. The join condition is equality of dept; distinct identifiers are retained.", "prompt": "Which statements are correct?", "options": [{"text": "The full outer join pairs employee 3 with department C to avoid NULL fields.", "correct": false, "why": "Outer joins preserve unmatched rows; they do not invent a match between unequal department values."}, {"text": "The inner join returns two tuples.", "correct": true, "why": "Only employees 1 and 2 match department A."}, {"text": "The left outer join with Employee on the left returns three tuples.", "correct": true, "why": "It adds employee 3 with NULL-extended department fields."}, {"text": "The right outer join returns four tuples.", "correct": false, "why": "It returns two matches for A and one unmatched C department: three tuples."}, {"text": "The full outer join returns four tuples.", "correct": true, "why": "It contains the two A matches, unmatched employee 3, and unmatched department C."}], "explanation": "Outer joins preserve designated unmatched tuples by NULL extension. They do not alter the matching predicate.", "source": "L08 slides 18–21"}, {"id": "p4q8", "type": "multi", "topic": "Rename in a self-join", "scenario": "An organisation stores Employee(eid,name,managerID). It needs each employee name beside that employee’s manager name. The same relation must participate twice.", "prompt": "Which design choices are correct?", "options": [{"text": "Project E.name and M.name after joining, with distinct output names.", "correct": true, "why": "Both names become available after the role-specific join and can be renamed for clarity."}, {"text": "Renaming a relation necessarily changes its tuple values.", "correct": false, "why": "Rename changes relation or attribute names, not stored values."}, {"text": "An inner self-join excludes an employee whose managerID has no matching manager tuple.", "correct": true, "why": "An inner join returns only matches; preserving such an employee requires an outer-join variant."}, {"text": "Create renamed copies E and M, then join on E.managerID=M.eid.", "correct": true, "why": "The aliases distinguish employee and manager roles and express the correct direction."}, {"text": "Join E.eid=M.eid to discover management links.", "correct": false, "why": "That matches an employee to themselves, not to the manager referenced by managerID."}], "explanation": "Self-joins need distinct relation roles. Renaming prevents ambiguity, while the actual predicate decides which roles are linked.", "source": "L08 slides 9–10, 16, 18"}, {"id": "p4q9", "type": "multi", "topic": "Projection before aggregation", "scenario": "A payroll analyst has Pay(eid,salary)={(1,100),(2,100),(3,200)}. Under set semantics, the analyst first computes π_salary(Pay), then counts its tuples and averages salary.", "prompt": "Which statements correctly compare aggregates before and after the projection?", "options": [{"text": "Aggregating the original Pay relation gives COUNT=3 and AVERAGE=133.33… .", "correct": true, "why": "The original relation retains both employees earning 100, so its sum is 400 across three tuples."}, {"text": "(2, 150), because the projected salary values are {100,200}.", "correct": true, "why": "Projection leaves two distinct values whose average is 150."}, {"text": "(2, 133.33…), because COUNT removes duplicates but AVERAGE does not.", "correct": false, "why": "Both aggregates receive the same two-tuple projected relation."}, {"text": "(3, 150), because the original employee keys remain hidden in the projection.", "correct": false, "why": "The keys are discarded, not retained as hidden tuple identifiers."}, {"text": "SUM over the projected salary relation is 300.", "correct": true, "why": "The projected input contains only 100 and 200, each once."}], "explanation": "Projecting salary first changes the population being aggregated from employees to distinct salary values.", "source": "L08 slides 6, 22–23"}, {"id": "p4q10", "type": "multi", "topic": "Grouping and threshold order", "scenario": "Sales(orderID,branch,amount) contains (1,N,80), (2,N,40), (3,S,70), (4,S,70). A manager wants branches whose total amount exceeds 100. γ groups and computes aggregates.", "prompt": "Which reasoning is sound?", "options": [{"text": "Both branches should be returned.", "correct": true, "why": "120 and 140 both satisfy the strict threshold."}, {"text": "Projecting only branch before the SUM is safe because amount exists in Sales.", "correct": false, "why": "The aggregate input would no longer contain amount."}, {"text": "Grouping by branch and summing amount yields N:120 and S:140.", "correct": true, "why": "Each branch total includes both of its orders."}, {"text": "Selecting amount>100 before grouping preserves the requested answer.", "correct": false, "why": "No individual order exceeds 100, although both group totals do."}, {"text": "Select total>100 after computing γ_branch; SUM(amount)→total(Sales).", "correct": true, "why": "The total attribute exists only after the grouped aggregate is computed."}], "explanation": "Row-level predicates and aggregate-level predicates answer different questions. Filter on a derived total after that total exists.", "source": "L08 slides 7–9, 22–23"}, {"id": "p4q11", "type": "multi", "topic": "Expressing a negative requirement", "scenario": "A club stores Member(mid,name) and Attendance(mid,event). It needs member identifiers that have never attended any event. Both relations use set semantics.", "prompt": "Which expressions or claims are correct?", "options": [{"text": "π_mid(Attendance) − π_mid(Member) answers the request.", "correct": false, "why": "It instead finds attendance identifiers not present in Member."}, {"text": "π_mid(Member ⋈ Attendance) directly gives members who never attended.", "correct": false, "why": "An inner join finds members with matching attendance, the opposite requirement."}, {"text": "If Attendance is empty, every member identifier is returned.", "correct": true, "why": "Subtracting the empty set leaves the complete member-id set."}, {"text": "Subtracting Attendance directly from Member is valid even though their second attributes have different meanings and domains.", "correct": false, "why": "The schemas must be aligned before set difference; the projected identifier relations provide that alignment."}, {"text": "π_mid(Member) − π_mid(Attendance) answers the request.", "correct": true, "why": "It subtracts every attended identifier from the set of members."}], "explanation": "Translate “never” into a set difference over the same identifier domain. Decide the universe first, then subtract disqualifying identifiers.", "source": "L08 slides 6, 11, 14, 16"}, {"id": "p4q12", "type": "multi", "topic": "Selecting an optimisation safely", "scenario": "A stock team evaluates π_pid(σ_region=\"West\" AND qty>0(Stock ⋈ Depot)), where Stock(pid,did,qty), Depot(did,region), and natural join uses only did. All conditions are ordinary non-NULL comparisons.", "prompt": "Which equivalent rewrites are valid?", "options": [{"text": "Apply the two selections separately in either order after the same inner join.", "correct": true, "why": "Conjunctive selections commute when all referenced attributes remain available."}, {"text": "Filter Stock by qty>0 and Depot by region=\"West\", then join and project pid.", "correct": true, "why": "Each filter uses attributes of only its own input and can be applied before this inner join."}, {"text": "Project Stock to pid alone before the join.", "correct": false, "why": "That removes did, so the intended join key is unavailable."}, {"text": "Project Stock to (pid,did) only after applying its qty filter, then join to the filtered Depot.", "correct": true, "why": "The quantity test has already been evaluated, and the join key plus output attribute remain."}, {"text": "Replace the two conditions joined by AND with OR.", "correct": false, "why": "That admits rows satisfying only one condition and changes the request."}], "explanation": "A safe rewrite preserves both the conditions and all attributes needed by later operators. Early filtering is not permission to discard a join key.", "source": "L08 slides 4, 6–9, 16–17"}, {"id": "p4q13", "type": "multi", "topic": "Why difference and projection do not commute", "scenario": "A transport analyst has R(route,day)={(A,Mon),(A,Tue)} and S(route,day)={(A,Mon)}. They compare π_route(R−S) with π_route(R)−π_route(S).", "prompt": "Which statements correctly describe these two valid algebra expressions?", "options": [{"text": "The first is {A}; the second is empty.", "correct": true, "why": "Difference first preserves the Tuesday tuple, while projection first makes both inputs equal to {A}."}, {"text": "The first is empty; the second is {A}.", "correct": false, "why": "This reverses the actual effects of the two operation orders."}, {"text": "Both expressions are well-defined, but they are not equivalent for this instance.", "correct": true, "why": "The schemas are compatible in both differences, but projection removes the day distinction at different stages."}, {"text": "Both results are {A}.", "correct": false, "why": "Projecting first loses the distinction between Monday and Tuesday; the projected difference becomes empty."}, {"text": "Both results are empty.", "correct": false, "why": "R−S still contains (A,Tue), which projects to A."}], "explanation": "Eliminating identifying detail before subtraction can change what counts as the same tuple. Projection does not generally distribute over difference.", "source": "L08 slides 6, 11, 14"}, {"id": "p4q14", "type": "multi", "topic": "Key-value access pattern", "scenario": "A ticket website retrieves a shopping basket using one unpredictable session token. Each request reads or replaces the whole basket. Cross-customer searches are not part of this workload.", "prompt": "Which conclusions are justified?", "options": [{"text": "A key-value store is a plausible fit because the dominant access path is a known key.", "correct": true, "why": "The requirement aligns with direct session-key lookup."}, {"text": "Choosing a key-value model proves that all future analytical queries will be efficient.", "correct": false, "why": "New access patterns may require indexes, another store, or redesigned data access."}, {"text": "The basket may be structured internally even if the store exposes it mainly as a value.", "correct": true, "why": "Key-value access does not require the application value to be meaningless bytes."}, {"text": "The team should evaluate expiry and concurrent basket-update requirements, not only the model label.", "correct": true, "why": "Operational and consistency requirements still determine suitability."}, {"text": "A key-value value may represent a basket containing several products.", "correct": true, "why": "The application can encode the collection within the value associated with its session key."}], "explanation": "Choose the model from how the application reads and updates data. A natural key-based workload is a reason to consider a key-value store, not proof of universal suitability.", "source": "L09 slides 14, 18–19"}, {"id": "p4q15", "type": "multi", "topic": "Document modelling", "scenario": "A museum catalogue has paintings with medium and dimensions, recordings with duration and performers, and manuscripts with language and pages. Item pages normally display one complete catalogue item.", "prompt": "Which proposals are defensible?", "options": [{"text": "Every document database must reject transactions by definition.", "correct": false, "why": "Transaction capabilities vary by product; this is not a defining universal restriction."}, {"text": "The ability to add a new optional field does not prove old application code will interpret it correctly.", "correct": true, "why": "Readers and validation rules must still account for schema evolution."}, {"text": "A document model can keep each item’s related descriptive fields together despite differing shapes.", "correct": true, "why": "Nested, varying records fit the stated item-oriented reads."}, {"text": "Flexible schema means a malformed identifier can never harm the application.", "correct": false, "why": "The application still depends on consistent identifiers and validation."}, {"text": "The team should define required fields and versioning rules even if optional fields differ.", "correct": true, "why": "Schema flexibility changes where rules are managed; it does not remove their need."}], "explanation": "Flexible document structure is useful for varied records, but data meaning, validation and application compatibility remain design responsibilities.", "source": "L09 slides 4–9, 15, 19, 21"}, {"id": "p4q16", "type": "multi", "topic": "Graph traversal", "scenario": "Investigators must repeatedly find accounts reachable from a suspicious account through up to five transfer relationships, preserving the path and relationship properties. Their data is highly connected.", "prompt": "Which statements support a careful model choice?", "options": [{"text": "The requirement can be reduced to independent session-key lookups without considering connectivity.", "correct": false, "why": "The requested paths depend on relationships between multiple accounts."}, {"text": "Path-query patterns and edge properties matter more than choosing a fashionable database category.", "correct": true, "why": "Those access requirements determine whether the model fits."}, {"text": "Using a graph model removes the need to control access to sensitive account data.", "correct": false, "why": "Security obligations remain regardless of the storage model."}, {"text": "A relational solution is logically impossible.", "correct": false, "why": "Relations can represent edges and support traversal; a graph model is a candidate fit, not the only possible representation."}, {"text": "A graph model directly represents the connected accounts and transfer relationships.", "correct": true, "why": "Nodes and edges match the dominant traversal problem."}], "explanation": "Highly connected path queries motivate evaluating a graph database. Model fit does not imply automatic performance or replace security design.", "source": "L09 slides 16, 18–19, 21"}, {"id": "p4q17", "type": "multi", "topic": "Column-family workload", "scenario": "An environmental platform receives millions of timestamped readings. Most reads retrieve recent readings for one sensor, and writes dominate the workload. The team is considering a column-family database.", "prompt": "Which considerations are sound?", "options": [{"text": "Data retention, growth and the busiest sensors should be considered before committing to a layout.", "correct": true, "why": "Skew and growth affect the practical performance and operation of a distributed design."}, {"text": "The heavy-write workload is a reason to evaluate a column-family model.", "correct": true, "why": "The lecture identifies heavy write volume as a common use case."}, {"text": "Partitioning all readings under one constant key guarantees balanced load.", "correct": false, "why": "A single constant key concentrates the workload instead of distributing it."}, {"text": "Designing around sensor and time access patterns is more useful than copying a relational schema unchanged.", "correct": true, "why": "Distributed NoSQL modelling is commonly driven by the expected queries."}, {"text": "Selecting this category guarantees that an arbitrary cross-sensor query will never scan much data.", "correct": false, "why": "Costs depend on the data layout and query path, not merely the category."}], "explanation": "A likely model fit still requires access-pattern and distribution design. Heavy writes alone do not make every key layout efficient.", "source": "L09 slides 5, 17–19, 21"}, {"id": "p4q18", "type": "multi", "topic": "CAP during a network partition", "scenario": "Two replicas lose communication. A completed price update is visible at replica A but not B. The service promises a response to every request reaching a non-failing replica during the partition. It allows B to return its older price.", "prompt": "Which conclusions follow in CAP terms?", "options": [{"text": "The stale response demonstrates that the stated consistency guarantee is not maintained.", "correct": true, "why": "A read after the completed update can return the earlier value."}, {"text": "CAP proves that the service can never be consistent again after the network recovers.", "correct": false, "why": "The theorem concerns guarantees during partitions, not permanent divergence."}, {"text": "Refusing some requests until coordination is restored would be a different trade-off.", "correct": true, "why": "That may preserve consistency at the expense of availability for those requests."}, {"text": "The service is prioritising availability over guaranteed latest/linearizable reads during this partition.", "correct": true, "why": "B responds despite being unable to confirm the completed update at A."}, {"text": "The two replicas can both guarantee the latest value for every request simply by waiting zero seconds.", "correct": false, "why": "Zero waiting cannot convey the missing update across the broken link."}], "explanation": "The relevant trade-off occurs when communication is partitioned. Responding from a stale isolated replica sacrifices guaranteed linearizable consistency.", "source": "L09 slides 10–11"}, {"id": "p4q19", "type": "multi", "topic": "Consistency versus availability", "scenario": "A stock reservation service must never confirm two sales of the last unit. During a partition, an isolated replica refuses reservation requests because it cannot coordinate with the replica holding the authoritative stock state.", "prompt": "Which interpretations of the stated CAP trade-off are justified?", "options": [{"text": "Keeping the server process running does not by itself establish CAP availability for reservations.", "correct": true, "why": "The required operation is refused even though the process is alive."}, {"text": "It sacrifices availability for some operations during the partition to protect consistency.", "correct": true, "why": "The isolated replica rejects reservations rather than risk incompatible confirmations."}, {"text": "It sacrifices partition tolerance because the network partition occurred.", "correct": false, "why": "Partition tolerance is about behaviour despite communication failure, not preventing all failures."}, {"text": "It has proved that all NoSQL systems are unsuitable for inventory.", "correct": false, "why": "The scenario describes a requirement and trade-off, not a universal judgement on database categories."}, {"text": "Allowing customers to retry after the partition does not make their present reservation requests available.", "correct": true, "why": "Future recovery does not satisfy availability during the current partition."}], "explanation": "CAP availability is a response guarantee for the relevant operations, not merely whether a machine is powered on. Refusal can be a deliberate correctness choice.", "source": "L09 slides 10–11"}, {"id": "p4q20", "type": "multi", "topic": "Eventual consistency and BASE", "scenario": "A photo service accepts a profile edit at one replica. Another replica temporarily displays the old profile. After updates stop and communication is restored, replication converges to one resolved profile.", "prompt": "Which conclusions are justified?", "options": [{"text": "Temporary stale values automatically prove permanent data loss.", "correct": false, "why": "A stale replica may simply be awaiting replication; permanence has not been established."}, {"text": "Users may need a design that distinguishes a pending edit from a globally visible edit.", "correct": true, "why": "The interaction can acknowledge the different visibility stages instead of promising immediate universal agreement."}, {"text": "This behaviour is compatible with eventual consistency.", "correct": true, "why": "Temporary divergence followed by convergence under the stated conditions matches the intended model."}, {"text": "Eventual consistency promises that every read immediately after an edit sees the edit.", "correct": false, "why": "Immediate visibility everywhere is stronger than eventual convergence."}, {"text": "The service still needs a conflict-resolution rule if independent replicas accept conflicting edits.", "correct": true, "why": "Convergence requires a way to reconcile competing updates."}], "explanation": "BASE-style design tolerates transitional states, but eventual consistency is not an excuse to omit convergence and conflict handling.", "source": "L09 slide 12; slides 18, 21"}, {"id": "p4q21", "type": "multi", "topic": "Do not confuse two meanings of consistency", "scenario": "A team compares ACID transactions with CAP. A transaction checks that every invoice amount is non-negative. Separately, replicas may serve different committed invoice versions during a partition.", "prompt": "Which statements are accurate?", "options": [{"text": "The business-rule check and the replica-visibility guarantee address different concerns.", "correct": true, "why": "ACID consistency and CAP consistency use the same word for distinct properties."}, {"text": "Both replicas can contain individually valid invoices while exposing different versions.", "correct": true, "why": "Validity against a domain rule does not require every replica to expose the latest committed state."}, {"text": "A NoSQL product cannot offer any transaction support.", "correct": false, "why": "Capabilities vary; NoSQL is not a universal ban on transactions."}, {"text": "The team should state the required read guarantee explicitly instead of relying on the word consistency alone.", "correct": true, "why": "Precise requirements prevent an invariant guarantee from being mistaken for a replica-ordering guarantee."}, {"text": "Passing the non-negative constraint alone proves CAP consistency between replicas.", "correct": false, "why": "A business invariant can hold in both an old and a new version while reads are not linearizable."}], "explanation": "Separate data-invariant preservation from distributed read/write consistency. Neither label by itself establishes every required guarantee.", "source": "L09 slides 7, 9–12, 21"}, {"id": "p4q22", "type": "multi", "topic": "Polyglot persistence", "scenario": "An online shop proposes a relational order ledger, a key-value session store and a graph recommendation service. The order ledger remains authoritative for payments.", "prompt": "Which assessments are reasonable?", "options": [{"text": "The team should decide how changes in authoritative orders reach the recommendation model.", "correct": true, "why": "Derived data needs an explicit update and recovery path."}, {"text": "The design is an example of polyglot persistence.", "correct": true, "why": "It intentionally uses different storage models for different application needs."}, {"text": "Each added store can introduce synchronisation and operational work.", "correct": true, "why": "Multiple systems create additional data movement, failure and monitoring responsibilities."}, {"text": "Recommendations being temporarily stale means the payment ledger must also accept stale balances.", "correct": false, "why": "Different subsystems can have different guarantees and authorities."}, {"text": "Using several databases automatically reduces all development and maintenance costs.", "correct": false, "why": "Better model fit may help, but integration and operations can also become more expensive."}], "explanation": "Polyglot persistence is a workload-based choice, not a free improvement. Preserve clear ownership of facts and explicit synchronisation rules.", "source": "L09 slides 18–21"}, {"id": "p4q23", "type": "multi", "topic": "Migrating relational data into documents", "scenario": "A school exports Student, Course and Enrolment tables into student documents, embedding course titles inside each student’s enrolment list. Course titles can change.", "prompt": "Which concerns or actions follow?", "options": [{"text": "The team should choose deliberately between embedded copies, references and acceptable staleness.", "correct": true, "why": "Those choices trade read convenience against update consistency and relationship handling."}, {"text": "Migration is complete as soon as every table has been converted into JSON text.", "correct": false, "why": "Data shape conversion does not establish correct queries, constraints or update behaviour."}, {"text": "Read patterns and course-change frequency are relevant to the embedding decision.", "correct": true, "why": "Frequent combined reads and frequent shared updates pull the design in different directions."}, {"text": "A title change may require updating several duplicated embedded copies.", "correct": true, "why": "Embedding creates repeated course facts across student documents."}, {"text": "The old relational foreign-key guarantees automatically survive the export.", "correct": false, "why": "The new storage and application design must provide the required relationship checks."}], "explanation": "Migration changes data ownership and constraint enforcement as well as storage syntax. Evaluate reads, updates and consistency together.", "source": "L09 slides 9, 15, 18–19, 21"}, {"id": "p4q24", "type": "multi", "topic": "Serverless and multi-model claims", "scenario": "A small analytics team is comparing a serverless NoSQL service with a database that supports documents and graphs. A proposal claims either option eliminates all modelling decisions.", "prompt": "Which responses are justified?", "options": [{"text": "Serverless deployment can reduce some infrastructure management, but does not remove query and data-model design.", "correct": true, "why": "Operational abstraction does not determine the correct representation or access patterns."}, {"text": "Supporting documents and graphs makes the second product multi-model.", "correct": true, "why": "The product exposes more than one data model."}, {"text": "Automatic scaling guarantees that every workload costs less than a fixed-capacity design.", "correct": false, "why": "Cost depends on workload, pricing and access efficiency; scaling alone is not a cost proof."}, {"text": "A multi-model database necessarily makes all data relationships consistent without any design rules.", "correct": false, "why": "Supported models still need integrity and update policies."}, {"text": "Governance, access control and data quality remain relevant for both options.", "correct": true, "why": "The lecture identifies increased focus on governance and consistency; neither deployment model removes those needs."}], "explanation": "Distinguish an operating model from a data model. Both serverless and multi-model capabilities still need workload, governance and consistency decisions.", "source": "L09 slides 18, 20–21"}, {"id": "p4q25", "type": "multi", "topic": "Requirements-led final decision", "scenario": "A university wants to replace a stable reporting database because a vendor advertises “NoSQL scales.” The workload has predictable joins and strict enrolment rules; the team has not measured a performance problem. A separate clickstream workload grows rapidly and mainly appends events.", "prompt": "Which recommendations are supported?", "options": [{"text": "Require a measured reason for changing the existing reporting design.", "correct": true, "why": "A migration should address actual requirements rather than assume a benefit from a trend."}, {"text": "Because clickstream data grows quickly, its retention and query patterns no longer matter.", "correct": false, "why": "Growth makes data access and lifecycle design more important, not less."}, {"text": "Replace both workloads immediately because the NoSQL label proves superior performance.", "correct": false, "why": "A category label is not evidence that a particular system or schema improves either workload."}, {"text": "Evaluate the two workloads separately against their actual access and consistency requirements.", "correct": true, "why": "Reporting joins and high-volume event ingestion can favour different designs."}, {"text": "Include migration, training, tooling and relationship-enforcement costs in the comparison.", "correct": true, "why": "The lecture identifies these as material modelling and operational challenges."}], "explanation": "Choose technology by demonstrated requirements and trade-offs. Different workloads may justify different decisions within the same organisation.", "source": "L09 slides 4–5, 18–21"}]}];